insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('5-3ecbd3f4b7','aux-cm',5,'Transcurrido el plazo de seis meses desde la iniciación del procedimiento de lesividad sin que se haya declarado, se produce:','["La declaración automática de lesividad", "La nulidad del acto", "La estimación del interesado por silencio", "La caducidad del procedimiento"]'::jsonb,3,'Art. 107.3 Ley 39/2015','Pasados seis meses sin declaración de lesividad, el procedimiento caduca.',null),
('6-57946c8e78','aux-cm',6,'En los casos de estimación por silencio, la resolución expresa posterior:','["Podrá ser desestimatoria si así lo aconseja el interés público", "Deberá someterse a dictamen previo del Consejo de Estado", "Solo podrá dictarse de ser confirmatoria del mismo", "Podrá ser confirmatoria o desestimatoria, según el resultado de la instrucción y las alegaciones de los interesados"]'::jsonb,2,'Art. 24.3 a) Ley 39/2015','La resolución expresa posterior a la estimación por silencio solo puede confirmarla.',null),
('1-7e3dce1add','aux-cm',1,'La nacionalidad española se adquiere, se conserva y se pierde:','["Solo por nacimiento o por residencia legal continuada", "Según lo que establezca cada Comunidad Autónoma en su Estatuto", "De acuerdo con lo establecido por la ley", "Por decisión del Gobierno, mediante real decreto acordado en Consejo de Ministros"]'::jsonb,2,'Art. 11.1 CE','Se adquiere, conserva y pierde de acuerdo con lo establecido por la ley.',null),
('1-387f465192','aux-cm',1,'El art. 40.2 encomienda a los poderes públicos garantizar el descanso necesario mediante:','["La jubilación anticipada y la reducción de la edad de jubilación", "La semana laboral de cuatro días y la jornada continua", "La limitación de la jornada laboral y las vacaciones periódicas retribuidas", "La limitación de la jornada laboral y los permisos retribuidos que fije cada convenio colectivo"]'::jsonb,2,'Art. 40.2 CE','Mediante la limitación de la jornada laboral, las vacaciones periódicas retribuidas y la promoción de centros adecuados.',null),
('6-a7b6e112b8','aux-cm',6,'Si el órgano competente para resolver considera que la infracción o la sanción revisten mayor gravedad que la propuesta, se notificará al inculpado para alegaciones en un plazo de:','["Quince días", "Diez días", "Cinco días", "Un mes"]'::jsonb,0,'Art. 90.2 Ley 39/2015','El inculpado dispone de quince días para alegar.',null),
('5-74b671cd05','aux-cm',5,'Iniciado un procedimiento de revisión de oficio o de lesividad, el órgano competente podrá suspender la ejecución del acto cuando:','["El acto sea favorable al interesado y este lo solicite antes de que se dicte la resolución", "Esta pudiera causar perjuicios de imposible o difícil reparación", "Lo solicite cualquier tercero, aunque no acredite la condición de interesado ni perjuicio alguno", "Hayan transcurrido seis meses desde que se dictó el acto"]'::jsonb,1,'Art. 108 Ley 39/2015','Puede suspenderse si la ejecución causaría perjuicios de imposible o difícil reparación.','oct. 2026 · 1.er ejercicio'),
('6-2081bdb21f','aux-cm',6,'Son interesados en el procedimiento, según el art. 4.1 a):','["Cualquier ciudadano, sin necesidad de acreditar interés alguno", "Quienes lo promuevan como titulares de derechos subjetivos, pero no de intereses legítimos colectivos", "Quienes tengan derechos que puedan resultar afectados por la decisión, aunque no se hayan personado", "Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos"]'::jsonb,3,'Art. 4.1 a) Ley 39/2015','También los que tengan derechos que puedan resultar afectados y los titulares de intereses legítimos que se personen antes de la resolución definitiva.',null),
('5-19f7e16966','aux-cm',5,'¿Ante quién se interpone el recurso extraordinario de revisión?','["Ante el Tribunal Superior de Justicia competente", "Ante el superior jerárquico del órgano que dictó el acto, que es competente para resolverlo", "Ante el órgano administrativo que dictó el acto, que también es competente para resolverlo", "Ante el superior jerárquico del órgano que dictó el acto, previo dictamen del Consejo de Estado"]'::jsonb,2,'Art. 125.1 Ley 39/2015','Se interpone y resuelve por el mismo órgano que dictó el acto.',null),
('1-64d2195989','aux-cm',1,'El derecho de reunión pacífica y sin armas:','["No necesita autorización previa", "Requiere autorización judicial", "Requiere autorización del Delegado del Gobierno", "Solo se ejerce en locales cerrados"]'::jsonb,0,'Art. 21.1 CE','Se reconoce el derecho de reunión pacífica y sin armas, cuyo ejercicio no necesita autorización previa.',null),
('6-b957d9912a','aux-cm',6,'Contra el acuerdo que resuelva sobre la ampliación del plazo máximo de resolución:','["Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "No cabrá recurso alguno", "Cabe recurso de alzada"]'::jsonb,2,'Art. 23.2 Ley 39/2015','Ese acuerdo no es recurrible.',null),
('6-e1b9d21bb7','aux-cm',6,'La ampliación excepcional del plazo máximo de resolución no podrá ser superior:','["A la mitad del plazo establecido para la tramitación del procedimiento", "Al plazo establecido para la tramitación del procedimiento", "A diez días hábiles", "A un año, cualquiera que sea el plazo inicial"]'::jsonb,1,'Art. 23.1 Ley 39/2015','Contra el acuerdo de ampliación no cabe recurso.',null),
('6-4b3373aa2b','aux-cm',6,'Si concurren varios interesados en un procedimiento de la AGE y existe discrepancia en cuanto a la lengua:','["Se tramitará en la lengua cooficial", "Lo decide el interesado que figure en primer lugar", "Se tramitará en ambas lenguas", "El procedimiento se tramitará en castellano"]'::jsonb,3,'Art. 15.1 Ley 39/2015','En caso de discrepancia, se tramita en castellano.',null),
('6-04ee4be6e7','aux-cm',6,'Los trámites que deban ser cumplimentados por los interesados se realizarán, salvo plazo distinto, en el plazo de:','["Diez días a partir del siguiente al de la notificación del correspondiente acto", "Cinco días a partir del siguiente al de la notificación", "Quince días a partir del siguiente al de la notificación del correspondiente acto", "Diez días a partir del mismo día de la notificación"]'::jsonb,0,'Art. 73.1 Ley 39/2015','El plazo general es de diez días.','abr. 2026 · 1.er ejercicio'),
('5-7796b29850','aux-cm',5,'La ejecución forzosa de los actos administrativos se efectuará:','["Solo con autorización judicial previa", "Siempre mediante compulsión sobre las personas", "Respetando siempre el principio de proporcionalidad y por los medios menos restrictivos de la libertad individual", "Respetando el principio de eficacia, por el medio más rápido disponible aunque no sea el menos restrictivo de la libertad individual"]'::jsonb,2,'Art. 99 Ley 39/2015','La ejecución forzosa respeta la proporcionalidad y elige el medio menos restrictivo.',null),
('6-3bd340a9e2','aux-cm',6,'La ampliación de un plazo y su solicitud deberán producirse:','["Solo el último día del plazo de que se trate", "En todo caso antes del vencimiento del plazo de que se trate", "Hasta diez días después del vencimiento del plazo, si se justifica la causa", "En cualquier momento"]'::jsonb,1,'Art. 32.3 Ley 39/2015','En ningún caso podrá ampliarse un plazo ya vencido.',null),
('1-c6ca683570','aux-cm',1,'Según el art. 10.1, son fundamento del orden político y de la paz social:','["La monarquía parlamentaria, la soberanía nacional y la unidad de la Nación española", "La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás", "La dignidad de la persona, la soberanía popular, la economía social de mercado, la unidad de la Nación española y la solidaridad entre sus nacionalidades y regiones", "La unidad de mercado y la libertad de empresa"]'::jsonb,1,'Art. 10.1 CE','Lo son la dignidad de la persona, sus derechos inviolables, el libre desarrollo de la personalidad y el respeto a la ley y a los derechos de los demás.','abr. 2026 · 1.er ejercicio'),
('6-00bf20b290','aux-cm',6,'Según el art. 54, los procedimientos podrán iniciarse:','["De oficio o a solicitud del interesado", "Solo de oficio, por propia iniciativa del órgano", "De oficio, a solicitud del interesado o por orden judicial", "Solo a solicitud"]'::jsonb,0,'Art. 54 Ley 39/2015','Las dos clases de iniciación son de oficio y a solicitud del interesado.',null),
('6-ab28066052','aux-cm',6,'La Administración puede abstenerse de resolver alegando silencio, oscuridad o insuficiencia de los preceptos legales:','["En ningún caso", "Sí, si lo autoriza el superior", "Sí, cuando la ley sea oscura", "Sí, en los procedimientos de oficio"]'::jsonb,0,'Art. 88.5 Ley 39/2015','Nunca puede abstenerse por esos motivos, aunque puede inadmitir solicitudes de derechos no previstos o manifiestamente carentes de fundamento.',null),
('6-2fb576837f','aux-cm',6,'En el procedimiento sancionador se podrá adoptar la tramitación simplificada cuando:','["El infractor sea reincidente y reconozca su responsabilidad", "Existan elementos de juicio suficientes para calificar la infracción como leve", "Existan elementos de juicio suficientes para calificar la infracción como leve o grave", "La infracción sea muy grave y urgente, o lo solicite expresamente el denunciante"]'::jsonb,1,'Art. 96.5 Ley 39/2015','Procede si la infracción se califica como leve.',null),
('6-08676676e6','aux-cm',6,'Las actuaciones complementarias deberán practicarse en un plazo no superior a:','["Un mes", "Quince días", "Siete días", "Tres meses"]'::jsonb,1,'Art. 87 Ley 39/2015','El plazo para resolver queda suspendido hasta su terminación.',null),
('5-703cbe87b8','aux-cm',5,'A efectos de entender cumplida la obligación de notificar dentro del plazo máximo, basta:','["Con firmar la resolución dentro del plazo máximo, aunque su notificación se intente después de vencido ese plazo legal", "Con remitir un aviso por SMS o correo electrónico", "La notificación que contenga el texto íntegro de la resolución y el intento de notificación debidamente acreditado", "Con publicar un anuncio en el tablón de edictos de la sede electrónica, aunque no se haya intentado la notificación personal"]'::jsonb,2,'Art. 40.4 Ley 39/2015','Es suficiente la notificación con el texto íntegro y el intento de notificación debidamente acreditado.',null),
('1-b0bc122980','aux-cm',1,'La estructura interna y el funcionamiento de los Colegios Profesionales deberán ser:','["Fijados por el Gobierno", "Secretos", "Democráticos", "Jerárquicos"]'::jsonb,2,'Art. 36 CE','La ley regulará los Colegios Profesionales, cuya estructura interna y funcionamiento deberán ser democráticos.',null),
('1-b2a081190c','aux-cm',1,'Según el art. 7, los sindicatos de trabajadores y las asociaciones empresariales deben tener:','["Una estructura interna y un funcionamiento democráticos", "Un número mínimo de afiliados que fije la ley orgánica correspondiente", "Autorización administrativa previa", "Inscripción en el Registro de Partidos Políticos"]'::jsonb,0,'Art. 7 CE','Su estructura interna y funcionamiento deberán ser democráticos.',null),
('5-72f0b5a252','aux-cm',5,'El apremio sobre el patrimonio procede cuando, en virtud del acto, haya de satisfacerse:','["Una obligación de no hacer", "Una cantidad líquida", "Una obligación de soportar", "Una obligación personalísima"]'::jsonb,1,'Art. 101.1 Ley 39/2015','Si hay que satisfacer cantidad líquida se sigue el procedimiento de apremio.',null),
('1-ff61b6881c','aux-cm',1,'La riqueza de las distintas modalidades lingüísticas de España es, según la Constitución:','["Un asunto de las Comunidades sin protección constitucional", "Un límite a la libertad de expresión", "Un patrimonio cultural objeto de especial respeto y protección", "Una competencia exclusiva del Estado"]'::jsonb,2,'Art. 3.3 CE','Es un patrimonio cultural que será objeto de especial respeto y protección.',null),
('6-7637828295','aux-cm',6,'También producirá la terminación del procedimiento:','["La falta de crédito presupuestario adecuado y suficiente", "La imposibilidad material de continuarlo por causas sobrevenidas, mediante resolución motivada", "La imposibilidad material de continuarlo, que se produce automáticamente sin necesidad de resolución", "El cambio del funcionario instructor, o la falta de crédito presupuestario adecuado para continuarlo"]'::jsonb,1,'Art. 84.2 Ley 39/2015','La resolución que se dicte deberá ser motivada en todo caso.',null),
('1-45879e68ad','aux-cm',1,'La ley garantiza el derecho a la negociación colectiva laboral y:','["La prohibición de los convenios de empresa", "El arbitraje obligatorio", "La aprobación de los convenios por el Gobierno", "La fuerza vinculante de los convenios"]'::jsonb,3,'Art. 37.1 CE','La ley garantizará el derecho a la negociación colectiva laboral, así como la fuerza vinculante de los convenios.',null),
('6-fad52d3df6','aux-cm',6,'Los actos de instrucción necesarios para determinar, conocer y comprobar los hechos se realizarán:','["Solo a instancia de los interesados y en papel, que deben proponer las actuaciones necesarias, sin que el órgano que tramite el procedimiento pueda acordarlas de oficio", "Por el órgano que tramite el procedimiento, en papel y sin uso de medios electrónicos, sin que los interesados puedan proponer actuaciones complementarias", "Por el instructor, a propuesta del Consejo de Estado", "De oficio y por medios electrónicos por el órgano que tramite el procedimiento, sin perjuicio del derecho de los interesados a proponer actuaciones"]'::jsonb,3,'Art. 75.1 Ley 39/2015','La instrucción se hace de oficio.',null),
('5-321ef8145e','aux-cm',5,'Según el art. 35.1 i), deben motivarse también:','["Las comunicaciones internas entre órganos", "Los actos reglados, sin excepción, aunque no limiten derechos ni intereses", "Los actos que se dicten en el ejercicio de potestades discrecionales", "Los actos de trámite que no decidan el fondo ni produzcan indefensión"]'::jsonb,2,'Art. 35.1 i) Ley 39/2015','Se motivan los actos dictados en ejercicio de potestades discrecionales y los que deban serlo por disposición legal.',null),
('5-8efd964d58','aux-cm',5,'En las Entidades Locales, la declaración de lesividad corresponde a:','["El Pleno de la Corporación o, en su defecto, el órgano colegiado superior de la entidad", "La Junta de Gobierno Local en todo caso, previo dictamen del órgano consultivo autonómico", "El Alcalde, dando cuenta al Pleno", "El Alcalde o, en su defecto, el Secretario municipal, previo informe preceptivo del Interventor"]'::jsonb,0,'Art. 107.5 Ley 39/2015','La adopta el Pleno o, en su defecto, el órgano colegiado superior.',null),
('6-171d8578a8','aux-cm',6,'En los procedimientos de responsabilidad patrimonial, el acuerdo alcanzado entre el interesado y el órgano competente deberá fijar:','["La culpa del funcionario causante del daño", "La sanción disciplinaria del empleado público responsable", "La cuantía de la indemnización, pero no el modo, que fija después el órgano competente", "La cuantía y el modo de indemnización"]'::jsonb,3,'Art. 86.5 Ley 39/2015','El acuerdo fija la cuantía y el modo de indemnización.',null),
('6-7fcf08bab1','aux-cm',6,'En los procedimientos iniciados de oficio, la Administración podrá desistir:','["Libremente y sin necesidad de motivación", "Motivadamente, en los supuestos y con los requisitos previstos en las leyes", "Solo con autorización judicial", "Motivadamente, en cualquier supuesto, sin necesidad de previsión legal"]'::jsonb,1,'Art. 93 Ley 39/2015','El desistimiento de la Administración debe ser motivado y legalmente previsto.',null),
('6-75b4a78b2c','aux-cm',6,'Las Administraciones podrán celebrar acuerdos, pactos, convenios o contratos que pongan fin al procedimiento siempre que:','["El interesado sea una persona jurídica y el acuerdo se refiera a materias de contenido económico o patrimonial", "No sean contrarios al ordenamiento jurídico ni versen sobre materias no susceptibles de transacción", "Se refieran a sanciones de cuantía inferior a 3.000 euros", "Lo autorice un juez"]'::jsonb,1,'Art. 86.1 Ley 39/2015','Es la terminación convencional.',null),
('1-9ac74c79ff','aux-cm',1,'Los extranjeros gozan en España de las libertades públicas del Título I:','["En ningún caso, salvo los derechos inherentes a la dignidad humana", "En igualdad absoluta con los españoles, incluido el derecho de sufragio en todas las elecciones", "Solo si residen legalmente más de cinco años", "En los términos que establezcan los tratados y la ley"]'::jsonb,3,'Art. 13.1 CE','Gozarán de las libertades públicas que garantiza el Título I en los términos que establezcan los tratados y la ley.',null),
('1-3d0bec7f16','aux-cm',1,'Las libertades del art. 20 tienen su límite, especialmente, en:','["La opinión mayoritaria de la sociedad, los intereses económicos del Estado y las instrucciones del Gobierno sobre la información pública", "Las instrucciones del Gobierno en materia de comunicación", "La seguridad nacional, el orden público, los intereses económicos del Estado y las instrucciones del Gobierno en materia de comunicación", "El derecho al honor, a la intimidad, a la propia imagen y la protección de la juventud y de la infancia"]'::jsonb,3,'Art. 20.4 CE','Tienen su límite en los demás derechos del Título I y, especialmente, en el honor, la intimidad, la propia imagen y la protección de la juventud y la infancia.',null),
('5-c5476a4fd8','aux-cm',5,'El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de:','["Aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción", "Ningún acto del procedimiento", "Los actos de trámite anteriores a la infracción, aunque su contenido hubiera variado de no cometerse esta", "Solo la resolución final y los actos de trámite posteriores a la infracción, aunque su contenido hubiera variado"]'::jsonb,0,'Art. 51 Ley 39/2015','Es el principio de conservación de actos y trámites.',null),
('5-50e7b26709','aux-cm',5,'Las Administraciones no iniciarán ninguna actuación material de ejecución que limite derechos de los particulares:','["Sin informe favorable del Consejo de Estado u órgano consultivo equivalente", "Sin el consentimiento expreso y por escrito del particular afectado por la actuación", "Sin que previamente haya sido adoptada la resolución que le sirva de fundamento jurídico", "Sin autorización judicial en todo caso"]'::jsonb,2,'Art. 97.1 Ley 39/2015','Es necesario un título previo: la resolución que sirve de fundamento jurídico.',null),
('6-498ec5e442','aux-cm',6,'Cuando razones de interés público lo aconsejen, podrá acordarse la tramitación de urgencia, que supone:','["Reducir todos los plazos a cinco días, incluidos los de recursos", "Suprimir los recursos administrativos", "Reducir a la mitad todos los plazos del procedimiento, incluidos los de presentación de solicitudes y recursos", "Reducir a la mitad los plazos del procedimiento ordinario, salvo los relativos a la presentación de solicitudes y recursos"]'::jsonb,3,'Art. 33.1 Ley 39/2015','Se reducen los plazos a la mitad, salvo los de solicitudes y recursos.',null),
('6-d458fffac2','aux-cm',6,'Solicitado el certificado acreditativo del silencio, este deberá emitirse en el plazo máximo de:','["Tres meses", "Diez días", "Un mes", "Quince días"]'::jsonb,3,'Art. 24.4 Ley 39/2015','El certificado del silencio se emite en un máximo de quince días.',null),
('6-e5a19c3cc3','aux-cm',6,'El instructor solo podrá rechazar las pruebas propuestas por los interesados cuando:','["Sean costosas para la Administración, aunque sean pertinentes y necesarias, mediante resolución motivada", "Sean manifiestamente improcedentes o innecesarias, mediante resolución motivada", "Sean improcedentes a su juicio, sin necesidad de motivar el rechazo ni notificarlo a los interesados", "Se propongan fuera del plazo de diez días"]'::jsonb,1,'Art. 77.3 Ley 39/2015','El rechazo de pruebas debe ser motivado y basarse en su improcedencia o innecesariedad manifiesta.',null),
('6-1b607bcfea','aux-cm',6,'Si un plazo fijado en meses vence en un mes en el que no hay día equivalente al de la notificación:','["El plazo expira el último día del mes", "El plazo se amplía 10 días", "El plazo expira el primer día del mes siguiente", "El plazo se considera vencido el día 28"]'::jsonb,0,'Art. 30.4 Ley 39/2015','Si no hay día equivalente, el plazo expira el último día del mes.',null),
('5-271f40cbb2','aux-cm',5,'Ponen fin a la vía administrativa:','["Los actos de trámite simples", "Las propuestas de resolución", "Las resoluciones de los recursos de alzada", "Los actos de órganos con superior jerárquico, como regla general"]'::jsonb,2,'Art. 114.1 a) Ley 39/2015','Las resoluciones de alzada ponen fin a la vía administrativa.',null),
('6-38c4b911ff','aux-cm',6,'El procedimiento está sometido al principio de:','["Rogación exclusiva del interesado, que lo impulsa en todos sus trámites mediante escritos sucesivos", "Celeridad, y se impulsará de oficio en todos sus trámites y a través de medios electrónicos", "Secreto de las actuaciones", "Oralidad, y se impulsará a instancia de los interesados en cada uno de sus trámites, en papel"]'::jsonb,1,'Art. 71.1 Ley 39/2015','El impulso es de oficio, con respeto a la transparencia y la publicidad.','abr. 2026 · 1.er ejercicio'),
('6-bb44c2950d','aux-cm',6,'En la petición de un informe se concretará:','["El plazo de tres meses para su emisión y el sentido del informe", "El extremo o extremos acerca de los que se solicita", "El sentido que debe tener el informe y el plazo para emitirlo", "El nombre del funcionario que debe emitirlo"]'::jsonb,1,'Art. 79.2 Ley 39/2015','Hay que concretar los extremos sobre los que se pide el informe.',null),
('6-19488a4d71','aux-cm',6,'Si durante la instrucción de un procedimiento no publicado se advierte la existencia de personas titulares de derechos o intereses legítimos que puedan resultar afectados:','["Se comunicará a dichas personas la tramitación del procedimiento", "No se les comunica nada hasta la resolución, que se les notifica", "Se suspenderá el procedimiento hasta que soliciten personarse", "Se archivará el procedimiento"]'::jsonb,0,'Art. 8 Ley 39/2015','Se les comunica la tramitación.',null),
('5-aef5447891','aux-cm',5,'El órgano que resuelva el recurso podrá suspender la ejecución del acto impugnado cuando:','["La impugnación se fundamente en alguna de las causas de nulidad de pleno derecho del art. 47.1", "La impugnación se fundamente en cualquier causa de anulabilidad, aunque la ejecución no cause perjuicios", "Lo pida un tercero no interesado en el procedimiento", "El acto sea favorable"]'::jsonb,0,'Art. 117.2 b) Ley 39/2015','También cuando la ejecución pueda causar perjuicios de imposible o difícil reparación.',null),
('6-1740012f9c','aux-cm',6,'La Administración está obligada a dictar resolución expresa y a notificarla:','["Solo en los procedimientos sancionadores", "En todos los procedimientos, cualquiera que sea su forma de iniciación", "Solo en los procedimientos iniciados a solicitud del interesado", "En todos los procedimientos, salvo en los iniciados de oficio, en que basta la caducidad"]'::jsonb,1,'Art. 21.1 Ley 39/2015','La obligación de resolver alcanza a todos los procedimientos, salvo las excepciones legales.',null),
('6-c13ef48e4b','aux-cm',6,'Si un día es hábil en el municipio del interesado e inhábil en la sede del órgano administrativo, o a la inversa:','["Se aplica el calendario del órgano", "Se aplica el calendario del interesado", "Se considerará inhábil en todo caso", "Se considerará hábil en todo caso"]'::jsonb,2,'Art. 30.6 Ley 39/2015','En caso de discrepancia, se considera inhábil.',null),
('6-64a55c1163','aux-cm',6,'La acumulación de procedimientos exige, entre otros requisitos, que:','["Lo soliciten todos los interesados por escrito", "Sea el mismo órgano quien deba tramitar y resolver el procedimiento", "Estén en la misma fase de tramitación y se refieran al mismo interesado o a interesados distintos", "Los interesados sean los mismos y los procedimientos estén en la misma fase"]'::jsonb,1,'Art. 57 Ley 39/2015','Se acumulan los que guarden identidad sustancial o íntima conexión y los tramite y resuelva el mismo órgano.',null),
('6-75dcab7537','aux-cm',6,'La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto, siempre que se aporte o subsane en el plazo de:','["Cinco días improrrogables desde el requerimiento, sin que el órgano pueda establecer otro plazo", "Quince días hábiles", "Un mes desde el requerimiento", "Diez días, o el plazo superior que establezca el órgano cuando las circunstancias lo requieran"]'::jsonb,3,'Art. 5.6 Ley 39/2015','El plazo para subsanar es de diez días.',null),
('1-d659d15a87','aux-cm',1,'Las penas privativas de libertad y las medidas de seguridad están orientadas a:','["El trabajo obligatorio en beneficio de la comunidad y la compensación económica a la víctima del delito", "La compensación económica a la víctima y a la sociedad", "La reeducación y la reinserción social, y no pueden consistir en trabajos forzados", "La reeducación y la reinserción social, y pueden incluir trabajos forzados en los casos que prevea la ley"]'::jsonb,2,'Art. 25.2 CE','Están orientadas hacia la reeducación y reinserción social y no podrán consistir en trabajos forzados.',null),
('6-65f1c619a0','aux-cm',6,'Según el art. 53.1 d), los interesados pueden formular alegaciones y aportar documentos:','["Solo en la solicitud inicial", "Solo en el período de prueba", "En cualquier fase del procedimiento anterior al trámite de audiencia", "En cualquier fase del procedimiento, incluso después de dictarse la resolución"]'::jsonb,2,'Art. 53.1 d) Ley 39/2015','Hasta el trámite de audiencia, que deberán ser tenidos en cuenta al redactar la propuesta de resolución.',null),
('5-bc4d03b9be','aux-cm',5,'Contra la resolución de un recurso de reposición:','["Cabe recurso de alzada", "No puede interponerse de nuevo dicho recurso", "Cabe un segundo recurso de reposición", "Cabe recurso de reposición ante el superior"]'::jsonb,1,'Art. 124.3 Ley 39/2015','No cabe reiterar la reposición.',null),
('6-d091ec3b4e','aux-cm',6,'Los interesados que conozcan datos que permitan identificar a otros interesados que no hayan comparecido en el procedimiento:','["Tienen prohibido comunicarlos por razones de protección de datos", "Pueden comunicarlos voluntariamente, sin estar obligados a ello", "Tienen el deber de proporcionárselos a la Administración actuante", "Solo deben comunicarlos ante un juez"]'::jsonb,2,'Art. 18.2 Ley 39/2015','Existe el deber de proporcionar esos datos a la Administración.',null),
('5-031edfe22c','aux-cm',5,'La publicación sustituye a la notificación, entre otros casos, cuando el acto:','["Se dicte en un procedimiento iniciado de oficio que afecte a varios interesados identificados", "Afecte a un único interesado identificado", "Tenga por destinatario a una pluralidad indeterminada de personas", "Sea una sanción leve impuesta a un interesado identificado y con domicilio conocido"]'::jsonb,2,'Art. 45.1 a) Ley 39/2015','También en los actos de procedimientos selectivos o de concurrencia competitiva.',null),
('1-c313d1389f','aux-cm',1,'Las Fuerzas Armadas están constituidas, según la Constitución, por:','["El Ejército de Tierra y la Policía Nacional", "El Ejército de Tierra, la Armada y el Ejército del Aire", "Las Fuerzas y Cuerpos de Seguridad del Estado", "El Ejército de Tierra, la Guardia Civil y la Armada"]'::jsonb,1,'Art. 8.1 CE','Las constituyen el Ejército de Tierra, la Armada y el Ejército del Aire.',null),
('1-0d7e8e5ae4','aux-cm',1,'Según el art. 33.3, nadie podrá ser privado de sus bienes y derechos sino:','["Por deudas con particulares reconocidas en sentencia firme", "Por orden del alcalde", "Por causa justificada de utilidad pública o interés social, sin indemnización cuando así lo decida el Gobierno mediante real decreto", "Por causa justificada de utilidad pública o interés social, mediante la correspondiente indemnización y de conformidad con la ley"]'::jsonb,3,'Art. 33.3 CE','Solo por causa justificada de utilidad pública o interés social, con indemnización y conforme a la ley.',null),
('6-2839382790','aux-cm',6,'Las Administraciones están obligadas a verificar la identidad de los interesados mediante la comprobación de:','["Su huella dactilar o cualquier otro dato biométrico que conste en el DNI o en el documento identificativo equivalente", "Su nombre y apellidos o denominación o razón social, que consten en el DNI o documento identificativo equivalente", "Su dirección de correo electrónico", "Su número de teléfono móvil"]'::jsonb,1,'Art. 9.1 Ley 39/2015','Se verifica con el nombre y apellidos o razón social del DNI o documento equivalente.',null),
('5-6e8fd96e51','aux-cm',5,'Si nadie se hace cargo de la notificación en papel en el domicilio, se repetirá:','["Dos veces en la misma semana, en horas distintas", "No se repite, y se publica directamente en el BOE", "Una sola vez y en una hora distinta dentro de los tres días siguientes", "Una sola vez y en la misma hora dentro de los cinco días siguientes"]'::jsonb,2,'Art. 42.2 Ley 39/2015','Se repite por una sola vez y en hora distinta dentro de los tres días siguientes.',null),
('6-25d485da49','aux-cm',6,'El incumplimiento de la obligación de dictar resolución expresa en plazo dará lugar a:','["La nulidad de pleno derecho del procedimiento", "Una sanción al interesado", "La estimación automática de la solicitud en todo caso, sin ninguna otra consecuencia para el órgano o para el personal responsable", "La exigencia de responsabilidad disciplinaria, sin perjuicio de la que hubiere lugar de acuerdo con la normativa aplicable"]'::jsonb,3,'Art. 21.6 Ley 39/2015','El personal y los titulares de órganos son responsables directos y responden disciplinariamente.',null),
('5-a086e2bce4','aux-cm',5,'Deben ser motivados, con sucinta referencia de hechos y fundamentos de derecho:','["Solo las disposiciones de carácter general y los actos que pongan fin a la vía administrativa", "Los actos que limiten derechos subjetivos o intereses legítimos", "Solo los actos favorables al interesado", "Todos los actos de trámite, aunque no limiten derechos ni decidan el fondo"]'::jsonb,1,'Art. 35.1 a) Ley 39/2015','El art. 35.1 a) exige motivar los actos que limiten derechos subjetivos o intereses legítimos.',null),
('6-49279b21ae','aux-cm',6,'Los interesados podrán aducir alegaciones y aportar documentos:','["En cualquier momento del procedimiento anterior al trámite de audiencia", "En cualquier momento, incluso tras la resolución", "Solo tras la propuesta de resolución", "Solo en los diez primeros días desde el inicio del procedimiento"]'::jsonb,0,'Art. 76.1 Ley 39/2015','Serán tenidos en cuenta al redactar la propuesta de resolución.',null),
('6-301f87276e','aux-cm',6,'Deberá acreditarse la representación para:','["Formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos", "Pedir información general sobre los procedimientos", "Consultar el estado del expediente", "Cualquier acto de mero trámite, incluida la consulta del expediente, la obtención de copias y la petición de información general"]'::jsonb,0,'Art. 5.3 Ley 39/2015','Para los actos de mero trámite la representación se presume.',null),
('1-cf08bfc166','aux-cm',1,'Según el art. 30.3, podrá establecerse:','["Un servicio civil para el cumplimiento de fines de interés general", "Un impuesto especial para la defensa nacional y la protección civil", "Un servicio militar universitario", "Una milicia en cada Comunidad Autónoma"]'::jsonb,0,'Art. 30.3 CE','Podrá establecerse un servicio civil para el cumplimiento de fines de interés general.',null),
('6-9b5a32cd58','aux-cm',6,'Si en un procedimiento simplificado el dictamen preceptivo del Consejo de Estado se manifiesta en contra del fondo de la propuesta de resolución:','["El órgano competente acordará continuar el procedimiento con arreglo a la tramitación ordinaria", "Se archiva el procedimiento", "Se resuelve igualmente según la propuesta de resolución", "El órgano competente acordará un nuevo trámite de audiencia y resolverá por la tramitación simplificada"]'::jsonb,0,'Art. 96.7 Ley 39/2015','Se pasa a la tramitación ordinaria.',null),
('1-e8bf5dbe47','aux-cm',1,'Según el art. 43.3, los poderes públicos fomentarán:','["El deporte profesional y de alto rendimiento, exclusivamente", "La medicina preventiva privada mediante conciertos con las mutuas sanitarias", "La educación sanitaria, la educación física y el deporte", "La educación física y el deporte escolar, pero no la educación sanitaria"]'::jsonb,2,'Art. 43.3 CE','Fomentarán la educación sanitaria, la educación física y el deporte, y facilitarán la adecuada utilización del ocio.',null),
('1-15d20e9441','aux-cm',1,'Según el art. 33.1, se reconoce el derecho:','["A la herencia, pero solo entre cónyuges y descendientes", "A la propiedad privada y a la herencia", "A la propiedad privada y a una vivienda en propiedad para cada familia", "A una renta mínima garantizada"]'::jsonb,1,'Art. 33.1 CE','Se reconoce el derecho a la propiedad privada y a la herencia.',null),
('6-aaf2389b57','aux-cm',6,'Las copias auténticas de documentos realizadas por los órganos competentes:','["Solo tienen validez dentro del mismo procedimiento en el que se expidieron", "Caducan a los seis meses de su expedición", "Tienen menos valor probatorio que el original, salvo que se compulsen ante notario", "Tendrán la misma validez y eficacia que los documentos originales"]'::jsonb,3,'Art. 27.2 Ley 39/2015','Las copias auténticas tienen la misma validez y eficacia que los originales.',null),
('6-31cffb4be3','aux-cm',6,'¿Cuál de los siguientes es un sistema de identificación electrónica previsto en el art. 9.2?','["Un mensaje desde un número de teléfono previamente comunicado", "El envío de una fotocopia escaneada del DNI por correo electrónico, junto con la solicitud firmada a mano", "Los sistemas basados en certificados electrónicos cualificados de firma electrónica", "Una llamada telefónica grabada"]'::jsonb,2,'Art. 9.2 Ley 39/2015','También los certificados cualificados de sello electrónico y otros sistemas que las AAPP consideren válidos.','oct. 2026 · 1.er ejercicio'),
('6-8fb46fca97','aux-cm',6,'Cuando la sanción tenga únicamente carácter pecuniario, el reconocimiento de responsabilidad y el pago voluntario dan lugar a reducciones de:','["Exactamente el 50 % del importe de la sanción propuesta, no acumulables", "El 30 % solo por pronto pago", "El 10 %, no acumulable", "Al menos el 20 % sobre el importe de la sanción propuesta, acumulables entre sí"]'::jsonb,3,'Art. 85.3 Ley 39/2015','Las reducciones son de al menos el 20 % cada una, acumulables, y pueden incrementarse reglamentariamente.',null),
('5-a6d058b09e','aux-cm',5,'Según el art. 38, los actos de las Administraciones sujetos al Derecho Administrativo son:','["Ejecutivos solo tras su confirmación judicial", "Ejecutivos con arreglo a lo dispuesto en la Ley", "Ejecutivos solo cuando sean firmes en vía administrativa y no se haya interpuesto recurso contencioso-administrativo", "Meramente declarativos hasta que se confirmen judicialmente"]'::jsonb,1,'Art. 38 Ley 39/2015','Los actos sujetos al Derecho Administrativo serán ejecutivos con arreglo a lo dispuesto en la Ley.',null),
('6-078b55a8b2','aux-cm',6,'Las cuestiones incidentales que se susciten en el procedimiento, incluso las que se refieran a la nulidad de actuaciones:','["Suspenden la tramitación, salvo la abstención", "Determinan el archivo provisional del procedimiento hasta su resolución por el órgano superior", "No suspenderán la tramitación del procedimiento, salvo la recusación", "Suspenden siempre la tramitación"]'::jsonb,2,'Art. 74 Ley 39/2015','Solo la recusación suspende el procedimiento.',null),
('1-cf246e2e5a','aux-cm',1,'Según el art. 38, se reconoce la libertad de empresa en el marco de:','["La economía de mercado", "La economía cooperativa exclusivamente", "La planificación central obligatoria", "El monopolio estatal"]'::jsonb,0,'Art. 38 CE','Se reconoce la libertad de empresa en el marco de la economía de mercado.',null),
('6-18f390adbf','aux-cm',6,'¿Cuál de las siguientes es una tipología de apoderamiento inscribible en el registro electrónico de apoderamientos?','["Un poder otorgado verbalmente ante el funcionario", "Un poder general para que el apoderado actúe en nombre del poderdante en cualquier actuación ante cualquier Administración", "Un poder especial para actuar ante los juzgados y tribunales penales en nombre del poderdante, en cualquier procedimiento", "Un poder sin identificar al apoderado"]'::jsonb,1,'Art. 6 Ley 39/2015','Las tipologías son: poder general, poder ante una Administración u Organismo concreto y poder para trámites específicos.',null),
('6-2db06776ea','aux-cm',6,'Según el principio de simplificación administrativa, se acordarán en un solo acto:','["Todos los recursos de un mismo interesado frente a actos distintos", "La iniciación, la instrucción y la resolución, cuando el procedimiento se tramite por la vía simplificada y lo solicite el interesado", "Todos los trámites de un mismo interesado, aunque sea obligado su cumplimiento sucesivo", "Todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo"]'::jsonb,3,'Art. 72.1 Ley 39/2015','Concentración de trámites.',null),
('5-7752c1e020','aux-cm',5,'Al declarar la nulidad de una disposición o acto, las Administraciones podrán:','["Establecer en la misma resolución las indemnizaciones que proceda reconocer a los interesados", "Exigir a los interesados el reintegro de lo percibido sin necesidad de procedimiento ni audiencia previa", "Imponer sanciones a los interesados que se beneficiaron del acto nulo, sin necesidad de procedimiento", "Dejar sin efecto las sentencias dictadas sobre el acto"]'::jsonb,0,'Art. 106.4 Ley 39/2015','Pueden fijar indemnizaciones si concurren los requisitos de responsabilidad patrimonial.',null),
('1-91aafa8f2b','aux-cm',1,'Según el art. 35.1, todos los españoles tienen:','["Solo el derecho al trabajo", "El deber de trabajar y el derecho al trabajo", "Derecho a no trabajar sin consecuencias", "Derecho a un empleo público"]'::jsonb,1,'Art. 35.1 CE','Tienen el deber de trabajar y el derecho al trabajo, a la libre elección de profesión u oficio y a una remuneración suficiente.',null),
('6-c26851f204','aux-cm',6,'Se entiende por documentos públicos administrativos:','["Los documentos privados presentados en un registro público", "Los documentos autorizados por notario, exclusivamente", "Los válidamente emitidos por los órganos de las Administraciones Públicas", "Cualquier documento firmado electrónicamente por un ciudadano y presentado en la sede electrónica de una Administración"]'::jsonb,2,'Art. 26.1 Ley 39/2015','Se emiten por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma.',null),
('1-3bec549b8b','aux-cm',1,'Según el art. 28.1, respecto a la libertad sindical:','["La afiliación es obligatoria para los funcionarios", "Nadie podrá ser obligado a afiliarse a un sindicato", "Solo pueden sindicarse los trabajadores fijos", "Los jueces pueden sindicarse sin límites"]'::jsonb,1,'Art. 28.1 CE','Todos tienen derecho a sindicarse libremente y nadie podrá ser obligado a afiliarse a un sindicato.',null),
('1-a7342a31b3','aux-cm',1,'El derecho de petición, según el art. 29.1:','["Solo pueden ejercerlo las asociaciones", "Requiere abogado", "Es individual y colectivo, por escrito", "Solo es individual y verbal"]'::jsonb,2,'Art. 29.1 CE','Todos los españoles tienen el derecho de petición individual y colectiva, por escrito.',null),
('6-1bf25a7c52','aux-cm',6,'La ampliación de plazos por el tiempo máximo permitido se aplicará en todo caso a los procedimientos tramitados por:','["Las Comunidades Autónomas cuando afecten a varias provincias", "Los órganos colegiados de cualquier Administración, y los que exijan algún trámite en otra Comunidad Autónoma", "Las misiones diplomáticas y oficinas consulares, y los que exijan algún trámite en el extranjero", "Los Ayuntamientos de municipios de gran población, y los que exijan algún trámite en otra Comunidad Autónoma"]'::jsonb,2,'Art. 32.2 Ley 39/2015','Se aplica a misiones diplomáticas, oficinas consulares y trámites en el extranjero o con interesados residentes fuera de España.',null),
('6-fc010c0d92','aux-cm',6,'Las Administraciones no exigirán a los interesados la presentación de documentos originales:','["Salvo en los procedimientos iniciados de oficio", "Salvo que, con carácter excepcional, la normativa reguladora aplicable establezca lo contrario", "En ningún caso, sin excepciones", "Salvo que el funcionario que tramite el procedimiento lo considere oportuno para comprobar su autenticidad"]'::jsonb,1,'Art. 28.3 Ley 39/2015','La regla es no exigir originales; solo excepcionalmente por normativa.',null),
('5-a6f744065e','aux-cm',5,'Es causa de inadmisión de un recurso:','["Que se presente en una oficina de Correos sin sello de fechas", "Que el recurrente no esté asistido de abogado", "Haber transcurrido el plazo para su interposición", "Que el recurrente haya calificado erróneamente el recurso, aunque se deduzca su verdadero carácter"]'::jsonb,2,'Art. 116 d) Ley 39/2015','Otras causas: incompetencia, falta de legitimación, acto no recurrible y carecer manifiestamente de fundamento.',null),
('5-c228ea29a5','aux-cm',5,'La compulsión sobre las personas procede, en los casos que la ley expresamente lo autorice, para:','["Obligaciones no personalísimas de hacer que puedan cumplirse por otro", "Cobrar cantidades líquidas", "Cualquier acto, a elección de la Administración", "Actos que impongan una obligación personalísima de no hacer o soportar"]'::jsonb,3,'Art. 104.1 Ley 39/2015','Se aplica a obligaciones personalísimas de no hacer o soportar, respetando la dignidad y los derechos constitucionales.',null),
('6-e5b1f3e233','aux-cm',6,'Si la resolución va a pronunciarse sobre cuestiones conexas no planteadas por los interesados, el órgano competente debe ponerlo de manifiesto a estos por un plazo:','["De tres días", "De un mes", "No superior a quince días", "No inferior a veinte días"]'::jsonb,2,'Art. 88.1 Ley 39/2015','Se da audiencia por plazo no superior a quince días.',null),
('1-11d991a819','aux-cm',1,'El art. 43 reconoce el derecho a:','["La asistencia sanitaria privada gratuita", "La protección de la salud", "La elección libre de médico en todo caso", "Un seguro de vida"]'::jsonb,1,'Art. 43.1 CE','Se reconoce el derecho a la protección de la salud.',null),
('6-90078c0fe9','aux-cm',6,'En los procedimientos sancionadores, la fase instructora y la sancionadora:','["Corresponderán al mismo órgano, salvo que la ley disponga otra cosa", "Las realiza el denunciante y el órgano competente, respectivamente", "Se tramitan como una sola fase", "Se encomendarán a órganos distintos"]'::jsonb,3,'Art. 63.1 Ley 39/2015','Los procedimientos sancionadores se inician siempre de oficio y separan instrucción y resolución.',null),
('1-02ecfce5dc','aux-cm',1,'El art. 47 reconoce a todos los españoles el derecho a:','["Una ayuda pública al alquiler en todo caso, de cuantía fija", "Una vivienda en propiedad a precio tasado", "Disfrutar de una vivienda digna y adecuada", "Disfrutar de una vivienda digna, que los poderes públicos deben adjudicar directamente a quien la solicite"]'::jsonb,2,'Art. 47 CE','Todos los españoles tienen derecho a disfrutar de una vivienda digna y adecuada.',null),
('1-17c26110f6','aux-cm',1,'Los poderes públicos garantizarán la conservación y promoverán el enriquecimiento de:','["Las empresas públicas y su patrimonio", "El patrimonio histórico, cultural y artístico de los pueblos de España", "El patrimonio histórico, cultural y artístico de titularidad pública, pero no el de titularidad privada", "Los bienes de la Corona"]'::jsonb,1,'Art. 46 CE','Garantizarán la conservación y promoverán el enriquecimiento del patrimonio histórico, cultural y artístico.',null),
('4-d02a9846c1','aux-cm',4,'Para que entren en vigor y produzcan efectos jurídicos, las normas con rango de ley, los reglamentos y disposiciones administrativas habrán de:','["Publicarse en el diario oficial correspondiente", "Firmarse por el Rey y comunicarse a las Cortes Generales", "Comunicarse a todos los Ayuntamientos y Diputaciones afectados", "Aprobarse por referéndum"]'::jsonb,0,'Art. 131 Ley 39/2015','La publicación en el diario oficial es requisito de entrada en vigor.',null),
('6-65fe6c05cf','aux-cm',6,'En la notificación de la práctica de una prueba se consignará el lugar, fecha y hora, con la advertencia de que el interesado:','["Puede nombrar técnicos para que le asistan", "Debe comparecer acompañado de notario o de abogado colegiado", "No puede asistir a su práctica", "Debe abonar en todo caso los gastos de la prueba"]'::jsonb,0,'Art. 78.2 Ley 39/2015','Se le advierte que puede nombrar técnicos que le asistan.',null),
('5-8f0fa7611a','aux-cm',5,'Excepcionalmente, se podrá otorgar eficacia retroactiva a los actos cuando:','["Sean sanciones más favorables que las anteriores", "Se trate de actos de gravamen que restrinjan derechos individuales y así lo prevea expresamente una norma reglamentaria", "Lo solicite cualquier tercero afectado y el acto restrinja derechos individuales del destinatario", "Se dicten en sustitución de actos anulados o produzcan efectos favorables al interesado"]'::jsonb,3,'Art. 39.3 Ley 39/2015','Cabe retroactividad cuando se dicten en sustitución de actos anulados o produzcan efectos favorables, si los supuestos de hecho existían y no se lesionan derechos de terceros.',null),
('6-b2d520233d','aux-cm',6,'En los procedimientos sancionadores, la orden superior de iniciación expresará, en la medida de lo posible:','["El sentido de la resolución que deba dictarse", "La sanción que corresponda imponer, el órgano competente para resolver, el instructor designado y el plazo máximo para dictar resolución", "El nombre del abogado defensor del presunto responsable y la sanción que corresponde imponerle según la tipificación", "La persona o personas presuntamente responsables, las conductas o hechos, su tipificación y el lugar y fecha"]'::jsonb,3,'Art. 60.2 Ley 39/2015','La orden superior debe concretar responsables, hechos, tipificación, lugar y fecha.',null),
('5-2df4c00212','aux-cm',5,'En la ejecución subsidiaria, el importe de los gastos podrá liquidarse:','["De forma provisional y realizarse antes de la ejecución, a reserva de la liquidación definitiva", "Por el doble de su coste, en concepto de sanción", "Nunca, porque los gastos los asume siempre la Administración que ejecuta", "Solo tras la ejecución, de forma definitiva y sin posibilidad de liquidación provisional"]'::jsonb,0,'Art. 102.4 Ley 39/2015','Cabe liquidación provisional previa a reserva de la definitiva; los gastos corren a cargo del obligado.',null),
('6-a5ad122f77','aux-cm',6,'Requerirán en todo caso la aprobación expresa del Consejo de Ministros u órgano equivalente de las CCAA:','["Todos los acuerdos convencionales que pongan fin a cualquier procedimiento", "Los acuerdos de los Ayuntamientos", "Los acuerdos que versen sobre materias de la competencia directa de dicho órgano", "Los acuerdos de cuantía superior a 6.000 €"]'::jsonb,2,'Art. 86.3 Ley 39/2015','Solo los que versen sobre materias de su competencia directa.',null),
('1-828965cfd1','aux-cm',1,'Según el art. 24.1, todas las personas tienen derecho a obtener la tutela efectiva de los jueces y tribunales:','["Sin que, en ningún caso, pueda producirse indefensión", "Solo en asuntos penales y contencioso-administrativos", "Solo si están asistidas de abogado y procurador", "Previo pago de las tasas judiciales correspondientes"]'::jsonb,0,'Art. 24.1 CE','Tienen derecho a la tutela judicial efectiva sin que, en ningún caso, pueda producirse indefensión.',null),
('6-1a8c29be44','aux-cm',6,'En la AGE, los procedimientos de responsabilidad patrimonial se resolverán, como regla general, por:','["El Ministro respectivo", "El Subsecretario", "El Presidente del Gobierno", "El Delegado del Gobierno"]'::jsonb,0,'Art. 92 Ley 39/2015','Por el Consejo de Ministros en los casos del art. 32.3 LRJSP o cuando una ley lo disponga.',null),
('6-2a330ba9c8','aux-cm',6,'Cuando se soliciten informes preceptivos a un órgano, el plazo máximo para resolver puede suspenderse por el tiempo que medie entre la petición y la recepción del informe, sin que pueda exceder de:','["Tres meses", "Seis meses", "Un mes", "Diez días"]'::jsonb,0,'Art. 22.1 d) Ley 39/2015','Esta suspensión no puede exceder en ningún caso de tres meses.',null),
('6-d482f915c4','aux-cm',6,'Los titulares de intereses legítimos que puedan resultar afectados por la resolución son interesados si:','["Se personan en el procedimiento en tanto no haya recaído resolución definitiva", "Lo solicitan antes del inicio del procedimiento", "Se personan en cualquier momento, incluso después de la resolución definitiva", "Lo autoriza el instructor"]'::jsonb,0,'Art. 4.1 c) Ley 39/2015','Deben personarse antes de la resolución definitiva.',null),
('1-53948c221e','aux-cm',1,'¿Qué prohíbe el art. 26 de la Constitución?','["Los colegios profesionales con adscripción obligatoria", "Los jurados populares en el ámbito penal", "Los tribunales militares en tiempo de guerra y en los supuestos de estado de sitio declarados por el Congreso", "Los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales"]'::jsonb,3,'Art. 26 CE','Se prohíben los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.',null),
('5-62d3c8870e','aux-cm',5,'Transcurridos tres meses desde la interposición del recurso extraordinario de revisión sin resolución:','["Caducará el procedimiento", "Se entenderá desestimado, quedando expedita la vía contencioso-administrativa", "Se entenderá estimado, salvo que el recurso se base en un error de hecho resultante de los documentos del expediente", "Se prorrogará otros tres meses"]'::jsonb,1,'Art. 126.3 Ley 39/2015','El silencio en el recurso extraordinario de revisión es desestimatorio.',null),
('6-d4f7225730','aux-cm',6,'En ningún caso se podrá imponer una sanción:','["Sin que se haya tramitado el oportuno procedimiento", "A una persona jurídica", "Superior a 600 euros sin autorización judicial", "Sin que el infractor esté asistido de abogado"]'::jsonb,0,'Art. 63.2 Ley 39/2015','La sanción exige siempre procedimiento previo.',null),
('5-ff075f36be','aux-cm',5,'La nulidad o anulabilidad de un acto:','["Implica siempre la nulidad de todo el procedimiento", "No implica la de los sucesivos en el procedimiento que sean independientes del primero", "Implica la de todos los actos posteriores del procedimiento, aunque sean independientes del primero", "Solo afecta a actos favorables"]'::jsonb,1,'Art. 49.1 Ley 39/2015','No se extiende a los actos sucesivos que sean independientes del primero.',null),
('6-884ef023e1','aux-cm',6,'En caso de desestimación por silencio, la resolución expresa posterior:','["No puede dictarse", "Se adoptará por la Administración sin vinculación alguna al sentido del silencio", "Debe ser necesariamente desestimatoria, en coherencia con el sentido del silencio producido", "Solo puede ser confirmatoria"]'::jsonb,1,'Art. 24.3 b) Ley 39/2015','En la estimación por silencio, en cambio, la resolución posterior solo puede ser confirmatoria.',null),
('1-d0569a7b78','aux-cm',1,'El art. 18.1 garantiza el derecho:','["Al honor, a la intimidad personal y familiar y a la propia imagen", "A la propiedad privada y a la herencia", "A la libertad de empresa en el marco de la economía de mercado", "Al secreto de las comunicaciones"]'::jsonb,0,'Art. 18.1 CE','Garantiza el derecho al honor, a la intimidad personal y familiar y a la propia imagen.',null),
('1-fe7a562c5b','aux-cm',1,'El derecho de fundación se reconoce:','["Para fines de interés general, con arreglo a la ley", "Solo a las empresas y sociedades mercantiles", "Solo para fines religiosos o benéficos", "Para cualquier fin, incluido el lucrativo, con arreglo a la ley"]'::jsonb,0,'Art. 34.1 CE','Se reconoce el derecho de fundación para fines de interés general, con arreglo a la ley.',null),
('5-aee2a99675','aux-cm',5,'El error o la ausencia de calificación del recurso por parte del recurrente:','["No será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter", "Obliga a presentarlo de nuevo", "Solo puede subsanarse si el recurrente está asistido de abogado", "Determina su inadmisión, salvo que el recurrente lo subsane en el plazo de diez días desde el requerimiento"]'::jsonb,0,'Art. 115.2 Ley 39/2015','Lo importante es que se deduzca el verdadero carácter del recurso.',null),
('5-6e33974816','aux-cm',5,'Los vicios y defectos que hagan anulable un acto:','["Solo pueden alegarse en vía judicial", "No podrán ser alegados por quienes los hubieren causado", "Determinan siempre la nulidad de pleno derecho del acto, aunque no causen indefensión", "Pueden alegarse por cualquier persona, incluidos quienes los hubieran causado"]'::jsonb,1,'Art. 115.3 Ley 39/2015','Quien causó el vicio no puede alegarlo.',null),
('6-5bb1183e5a','aux-cm',6,'El acuerdo de realización de actuaciones complementarias se notificará a los interesados, concediéndoles un plazo para alegaciones tras su finalización de:','["Siete días", "Cinco días", "Quince días", "Diez días"]'::jsonb,0,'Art. 87 Ley 39/2015','Plazo de siete días para alegaciones; las actuaciones se practican en un máximo de quince días y el plazo para resolver queda suspendido.',null),
('6-e60bee0a7d','aux-cm',6,'Tienen capacidad de obrar ante las Administraciones Públicas:','["Solo los españoles mayores de edad", "Las personas físicas o jurídicas que la ostenten con arreglo a las normas civiles", "Solo los mayores de 21 años y las personas jurídicas inscritas en un registro público", "Las personas físicas o jurídicas con certificado digital, aunque no tengan capacidad conforme a las normas civiles"]'::jsonb,1,'Art. 3 a) Ley 39/2015','Tienen capacidad las personas que la tengan según las normas civiles.',null),
('1-3ebc1b7b44','aux-cm',1,'Según el art. 9.1, están sujetos a la Constitución y al resto del ordenamiento jurídico:','["Solo los ciudadanos españoles", "Solo los funcionarios y los poderes públicos", "Solo los poderes públicos y los funcionarios", "Los ciudadanos y los poderes públicos"]'::jsonb,3,'Art. 9.1 CE','Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico.',null),
('6-06dde46284','aux-cm',6,'En los procedimientos iniciados de oficio de los que pudiera derivarse el reconocimiento de derechos o situaciones favorables, el vencimiento del plazo sin resolución permite a los interesados:','["Entender desestimadas sus pretensiones por silencio administrativo", "Entender estimadas sus pretensiones por silencio administrativo positivo", "Solicitar que se declare la caducidad del procedimiento", "Exigir una indemnización automática"]'::jsonb,0,'Art. 25.1 a) Ley 39/2015','En estos procedimientos el silencio es desestimatorio.',null),
('6-02587e4895','aux-cm',6,'La comparecencia en el trámite de información pública:','["Solo pueden hacerla los vecinos del municipio afectado", "Es obligatoria para poder recurrir después la resolución", "Convierte en interesado al compareciente", "No otorga, por sí misma, la condición de interesado"]'::jsonb,3,'Art. 83.3 Ley 39/2015','La incomparecencia tampoco impide a los interesados recurrir la resolución.',null),
('1-d8d167aeeb','aux-cm',1,'Las prestaciones personales o patrimoniales de carácter público solo pueden establecerse:','["Con arreglo a la ley", "Por reglamento", "Por orden ministerial", "Por acuerdo municipal"]'::jsonb,0,'Art. 31.3 CE','Solo podrán establecerse prestaciones personales o patrimoniales de carácter público con arreglo a la ley.',null),
('6-45e351de5b','aux-cm',6,'Contra el acuerdo de acumulación de procedimientos:','["No procederá recurso alguno", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "Cabe recurso de alzada"]'::jsonb,0,'Art. 57 Ley 39/2015','La acumulación procede si hay identidad sustancial o íntima conexión y el mismo órgano tramita y resuelve.',null),
('6-056f4f7524','aux-cm',6,'Si la Administración acuerda de oficio la tramitación simplificada y algún interesado manifiesta su oposición expresa:','["Se mantiene la tramitación simplificada si el órgano lo motiva por razones de interés público", "Se mantiene la tramitación simplificada", "Se mantiene la tramitación simplificada si el órgano lo motiva", "La Administración deberá seguir la tramitación ordinaria"]'::jsonb,3,'Art. 96.2 Ley 39/2015','La oposición expresa de un interesado obliga a la tramitación ordinaria.',null),
('6-659099d52d','aux-cm',6,'La resolución que ponga fin al procedimiento sancionador será ejecutiva cuando:','["Lo decida motivadamente el instructor del procedimiento", "No quepa contra ella ningún recurso ordinario en vía administrativa", "Se notifique al interesado, aunque quepa contra ella recurso de alzada", "Se dicte por el órgano competente, aunque quepa contra ella recurso de alzada"]'::jsonb,1,'Art. 90.3 Ley 39/2015','Puede suspenderse cautelarmente si el interesado manifiesta que interpondrá recurso contencioso-administrativo.',null),
('6-35858f504f','aux-cm',6,'Si la cuestión suscitada entrañase interés general, la Administración ante un desistimiento o renuncia:','["Podrá limitar sus efectos al interesado y seguirá el procedimiento", "Deberá aceptarlo de plano y declarar concluso el procedimiento para todos los interesados", "Deberá archivar el procedimiento", "Deberá pedir dictamen al Consejo de Estado"]'::jsonb,0,'Art. 94.5 Ley 39/2015','El procedimiento continúa por el interés general.',null),
('1-da84e826a1','aux-cm',1,'Según el art. 44.2, los poderes públicos promoverán:','["La investigación militar y de defensa, y la cooperación científica con las Fuerzas Armadas aliadas", "Solo la investigación sanitaria y farmacéutica", "La investigación privada exclusivamente, mediante incentivos fiscales a las empresas", "La ciencia y la investigación científica y técnica en beneficio del interés general"]'::jsonb,3,'Art. 44.2 CE','Promoverán la ciencia y la investigación científica y técnica en beneficio del interés general.',null),
('6-bb5c9d16e4','aux-cm',6,'Si un informe preceptivo no se emite en plazo:','["Se entiende desfavorable a la pretensión del interesado y se continúa el procedimiento hasta su resolución", "Se entiende favorable", "Se podrá suspender el transcurso del plazo máximo legal para resolver el procedimiento", "Se archiva el procedimiento"]'::jsonb,2,'Art. 80.3 Ley 39/2015','Si no es preceptivo, se pueden proseguir las actuaciones.',null),
('6-18e4520f38','aux-cm',6,'Según el art. 3 c), los grupos de afectados y las entidades sin personalidad jurídica tienen capacidad de obrar:','["Siempre, cualquiera que sea su número de miembros", "Cuando tengan más de 20 miembros", "Cuando la ley así lo declare expresamente", "Cuando se inscriban en el registro correspondiente de la Administración ante la que actúen"]'::jsonb,2,'Art. 3 c) Ley 39/2015','Grupos de afectados, uniones y entidades sin personalidad y patrimonios independientes tienen capacidad cuando la ley lo declare expresamente.',null),
('4-1a8b8d85d3','aux-cm',4,'¿Cuáles son los principios de buena regulación del art. 129 de la Ley 39/2015?','["Eficacia, jerarquía, descentralización, desconcentración y coordinación", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia", "Igualdad, mérito, capacidad y publicidad", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, publicidad y jerarquía"]'::jsonb,1,'Art. 129.1 Ley 39/2015','Son seis principios de buena regulación.',null),
('6-45f52ceedf','aux-cm',6,'Si un interesado solicita la tramitación simplificada y el órgano considera que no procede, podrá desestimarla en el plazo de:','["Cinco días desde su presentación, sin posibilidad de recurso", "Un mes desde su presentación, con recurso de alzada", "Diez días desde su presentación, con recurso de alzada", "Cinco días desde su presentación, con recurso potestativo de reposición"]'::jsonb,0,'Art. 96.3 Ley 39/2015','Transcurrido el plazo sin resolver, se entiende desestimada.',null),
('1-322734bdbf','aux-cm',1,'¿Quién establece los términos en que extranjeros y apátridas pueden gozar del derecho de asilo?','["Los tratados exclusivamente", "La ley", "El Defensor del Pueblo", "El Ministerio del Interior por orden"]'::jsonb,1,'Art. 13.4 CE','La ley establecerá los términos en que los ciudadanos de otros países y los apátridas podrán gozar del derecho de asilo.',null),
('1-8020d450bf','aux-cm',1,'¿Qué regula la ley según el art. 20.3?','["La censura previa de los medios de comunicación privados", "Las tarifas publicitarias y el régimen de concesión de licencias de los medios de comunicación privados de ámbito estatal", "El control parlamentario de los medios de comunicación social dependientes del Estado o de cualquier ente público", "El control gubernamental de todos los medios de comunicación social, públicos y privados, a través de una autoridad independiente"]'::jsonb,2,'Art. 20.3 CE','La ley regulará la organización y el control parlamentario de los medios dependientes del Estado o de cualquier ente público.',null),
('4-d69ce1fa4d','aux-cm',4,'Los reglamentos y disposiciones administrativas NO podrán:','["Desarrollar una ley", "Publicarse en el BOE", "Regular la organización interna de la Administración ni el funcionamiento de sus órganos colegiados y unidades administrativas", "Tipificar delitos, faltas o infracciones administrativas, establecer penas o sanciones, ni tributos"]'::jsonb,3,'Art. 128.2 Ley 39/2015','Tampoco vulnerar la Constitución o las leyes ni regular materias reservadas a las Cortes o a las Asambleas autonómicas.',null),
('1-7131ef21d7','aux-cm',1,'Respecto a la extradición, la Constitución establece que:','["No se consideran delitos políticos los actos de terrorismo", "Solo la concede el Gobierno, sin intervención judicial", "Se concede sin necesidad de tratado ni de ley, por reciprocidad", "Está prohibida en todo caso respecto de los nacionales"]'::jsonb,0,'Art. 13.3 CE','La extradición se concede en cumplimiento de un tratado o de la ley, atendiendo a la reciprocidad; los actos de terrorismo no se consideran delitos políticos.',null),
('4-bca2e988a5','aux-cm',4,'Según la Ley 39/2015, el Gobierno de la Nación ejercerá la iniciativa legislativa en los términos de la Constitución mediante:','["La iniciativa legislativa popular", "Las proposiciones de ley del Senado", "La elaboración y aprobación de los anteproyectos de ley y la remisión de los proyectos de ley a las Cortes Generales", "La elaboración de proposiciones de ley que remite a las Cortes Generales a través del Consejo de Estado"]'::jsonb,2,'Art. 127 Ley 39/2015','También podrá aprobar reales decretos-leyes y reales decretos legislativos.',null),
('5-76c4333504','aux-cm',5,'Si el vicio de un acto consiste en incompetencia no determinante de nulidad, la convalidación podrá realizarse por:','["El interesado afectado, mediante escrito en el que manifieste su conformidad con el acto viciado", "El órgano competente, cuando sea superior jerárquico del que dictó el acto viciado", "El propio órgano que dictó el acto, mediante una resolución posterior que subsane el vicio de incompetencia", "El Defensor del Pueblo"]'::jsonb,1,'Art. 52.3 Ley 39/2015','La incompetencia no determinante de nulidad se convalida por el órgano competente superior jerárquico.',null),
('5-c1cfae8f85','aux-cm',5,'Las Administraciones podrán practicar notificaciones por medios no electrónicos cuando:','["Para asegurar la eficacia de la actuación sea necesario practicarla por entrega directa de un empleado público", "Sea fin de semana", "La notificación sea favorable al interesado", "El interesado esté obligado a relacionarse electrónicamente con la Administración y no haya accedido a la notificación"]'::jsonb,0,'Art. 41.2 b) Ley 39/2015','También cuando el interesado comparezca espontáneamente en una oficina de asistencia y solicite la comunicación personal.',null),
('1-bcd8eb30b0','aux-cm',1,'Toda persona detenida debe ser informada:','["Solo si lo solicita su abogado o un familiar", "En el plazo máximo de 72 horas, una vez puesta a disposición judicial y en presencia de su abogado", "Solo cuando sea puesta a disposición judicial, en presencia de su abogado y en el plazo de setenta y dos horas", "De forma inmediata y comprensible de sus derechos y de las razones de su detención"]'::jsonb,3,'Art. 17.3 CE','Debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de las razones de su detención.',null),
('5-26c2b4f85c','aux-cm',5,'El recurso de alzada se interpone ante:','["El Tribunal Superior de Justicia de la Comunidad Autónoma", "El Consejo de Estado", "El órgano superior jerárquico del que dictó el acto, pudiendo presentarse ante el que lo dictó o ante el competente para resolver", "El mismo órgano que dictó el acto, que lo resuelve en el plazo de un mes, sin que pueda presentarse ante el superior jerárquico ni ante otro órgano"]'::jsonb,2,'Art. 121.1 Ley 39/2015','Lo resuelve el superior jerárquico; puede presentarse ante cualquiera de los dos.',null),
('5-8e604a459a','aux-cm',5,'Si el órgano aprecia que la publicación íntegra de un acto lesiona derechos o intereses legítimos:','["Se publicará íntegramente igualmente, sin perjuicio de la responsabilidad patrimonial que proceda por los daños causados a los interesados afectados", "No se publicará ni notificará el acto, y el órgano se limitará a comunicar a los interesados que existe una resolución que les afecta", "Se enviará al Defensor del Pueblo", "Se limitará a publicar una somera indicación del contenido y del lugar donde los interesados pueden comparecer para conocerlo"]'::jsonb,3,'Art. 46 Ley 39/2015','Se publica una somera indicación del contenido y del lugar donde comparecer en el plazo que se establezca.',null),
('6-23963afc5a','aux-cm',6,'Los expedientes tendrán formato electrónico y se formarán mediante la agregación ordenada de documentos, con:','["Un sello en papel en cada documento", "Un resumen elaborado por el instructor con la relación de los interesados y de los trámites realizados", "La firma de todos los interesados en cada uno de los documentos que contenga", "Un índice numerado de todos los documentos que contenga cuando se remita"]'::jsonb,3,'Art. 70.2 Ley 39/2015','Deben incluir un índice numerado de todos los documentos.',null),
('1-09ff69925a','aux-cm',1,'Según la Constitución, ¿puede alguien ser obligado a declarar sobre su ideología, religión o creencias?','["No", "Sí, ante un juez", "Sí, en los censos oficiales", "Solo los funcionarios"]'::jsonb,0,'Art. 16.2 CE','Nadie podrá ser obligado a declarar sobre su ideología, religión o creencias.',null),
('5-e081904f08','aux-cm',5,'Las notificaciones por medios electrónicos se entienden practicadas:','["Al día siguiente de su emisión", "Cuando el interesado contesta", "Cuando se envía al interesado el aviso de puesta a disposición por correo electrónico o SMS", "En el momento en que se produzca el acceso a su contenido"]'::jsonb,3,'Art. 43.2 Ley 39/2015','Se entienden practicadas en el momento del acceso a su contenido.',null),
('1-9a3982649b','aux-cm',1,'Respecto al medio ambiente, el art. 45.1 reconoce:','["El derecho a disfrutar de un medio ambiente adecuado y el deber de conservarlo", "El derecho a disfrutar de un medio ambiente adecuado, sin establecer ningún deber de conservarlo", "El derecho a explotarlo libremente", "El deber de conservarlo, pero no el derecho a disfrutarlo, que se regula en los Estatutos"]'::jsonb,0,'Art. 45.1 CE','Todos tienen el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como el deber de conservarlo.',null),
('4-cefb8c0ca3','aux-cm',4,'Según el principio de eficiencia del art. 129.6, la iniciativa normativa debe:','["Aumentar los trámites para garantizar el control", "Aprobarse sin consulta pública previa ni trámite de audiencia, para reducir la duración del procedimiento normativo", "Evitar cargas administrativas innecesarias o accesorias y racionalizar la gestión de los recursos públicos", "Evitar cargas administrativas innecesarias, aunque suponga aumentar el gasto público y crear nuevos órganos"]'::jsonb,2,'Art. 129.6 Ley 39/2015','Eficiencia: evitar cargas innecesarias o accesorias.',null),
('6-1a099a3bae','aux-cm',6,'En el asiento de registro debe constar, entre otros datos:','["La firma del superior jerárquico del órgano destinatario y el sello de la oficina que lo recibe", "Un número, epígrafe expresivo de su naturaleza, fecha y hora de presentación, identificación del interesado y referencia al contenido", "Un número, fecha de presentación, identificación del interesado y del órgano destinatario, pero no la hora de presentación ni ninguna referencia a su contenido", "El sentido previsible de la resolución"]'::jsonb,1,'Art. 16.2 Ley 39/2015','Se emite recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada.','oct. 2026 · 1.er ejercicio'),
('1-8f72c3b71a','aux-cm',1,'Las banderas propias de las Comunidades Autónomas:','["Las aprueba el Gobierno de la Nación a propuesta de cada Comunidad", "Están prohibidas en los edificios públicos del Estado", "Sustituyen a la bandera de España en los edificios y actos oficiales de su territorio, si así lo dispone su Estatuto", "Pueden ser reconocidas por los Estatutos y se utilizan junto a la bandera de España en sus edificios y actos oficiales"]'::jsonb,3,'Art. 4.2 CE','Los Estatutos pueden reconocerlas; se usan junto a la bandera de España en sus edificios públicos y actos oficiales.',null),
('6-482019e745','aux-cm',6,'Es un derecho de las personas en sus relaciones con las AAPP según el art. 13:','["Elegir al funcionario que tramite su expediente", "Obtener una resolución favorable si la Administración incumple el plazo máximo para resolver", "Ser tratados con respeto y deferencia por las autoridades y empleados públicos", "Ser atendidos en la lengua que elijan, cualquiera que sea la Administración"]'::jsonb,2,'Art. 13 e) Ley 39/2015','Otros: comunicarse por el Punto de Acceso General electrónico, ser asistidos en el uso de medios electrónicos, usar lenguas cooficiales, acceso a información pública…',null),
('6-24a3958298','aux-cm',6,'La resolución en un procedimiento de responsabilidad patrimonial deberá pronunciarse sobre:','["La responsabilidad penal del empleado público que causó el daño y la sanción disciplinaria que le corresponda imponer", "La sanción disciplinaria al funcionario responsable y la cuantía de la indemnización", "La existencia o no de relación de causalidad, la valoración del daño y la cuantía y modo de indemnización", "La existencia de culpa o dolo del empleado, que es requisito para que nazca la responsabilidad de la Administración"]'::jsonb,2,'Art. 91.2 Ley 39/2015','Son los extremos obligatorios de la resolución.',null),
('6-740299bbe9','aux-cm',6,'No se podrán adoptar medidas provisionales que:','["Sean proporcionadas al objetivo que se pretende garantizar, aunque se adopten antes del inicio del procedimiento en casos de urgencia", "Se adopten una vez iniciado el procedimiento, sin audiencia previa del interesado", "Afecten a la actividad económica del interesado o a su patrimonio, aunque no le causen ningún perjuicio de difícil o imposible reparación ni vulneren sus derechos", "Puedan causar perjuicio de difícil o imposible reparación a los interesados o impliquen violación de derechos amparados por las leyes"]'::jsonb,3,'Art. 56.4 Ley 39/2015','Las medidas provisionales tienen ese límite.',null),
('6-68be360167','aux-cm',6,'En la tramitación simplificada, el trámite de audiencia solo se realiza cuando:','["Nunca, porque la tramitación simplificada lo suprime en todo caso", "Siempre, como en la tramitación ordinaria", "Lo pida cualquier tercero que no sea interesado", "La resolución vaya a ser desfavorable para el interesado"]'::jsonb,3,'Art. 96.6 d) Ley 39/2015','Las alegaciones al inicio se formulan en cinco días.',null),
('6-2334908c9e','aux-cm',6,'Los términos y plazos establecidos en las leyes obligan:','["Solo a la Administración, que debe resolver en el plazo máximo", "Solo a los interesados, que pierden su derecho si no los cumplen", "A las autoridades y personal al servicio de las Administraciones competentes para la tramitación, así como a los interesados", "A las autoridades y personal de la Administración, pero no a los interesados, que pueden cumplir los trámites en cualquier momento"]'::jsonb,2,'Art. 29 Ley 39/2015','Los plazos obligan tanto a la Administración como a los interesados.',null),
('5-117524a615','aux-cm',5,'La eficacia de un acto quedará demorada cuando:','["Se haya dictado en el mes de agosto o en un periodo vacacional, salvo que el interesado solicite su eficacia inmediata", "El interesado lo solicite verbalmente", "Así lo exija su contenido o esté supeditada a su notificación, publicación o aprobación superior", "Así lo decida el funcionario instructor, aunque su contenido no lo exija ni dependa de notificación o aprobación"]'::jsonb,2,'Art. 39.2 Ley 39/2015','La eficacia se demora cuando lo exija el contenido del acto o esté supeditada a notificación, publicación o aprobación superior.',null),
('6-84df33c011','aux-cm',6,'No se tendrán por presentados en el registro:','["Aquellos documentos e información cuyo régimen especial establezca otra forma de presentación", "Los presentados por un representante cuya representación no esté inscrita", "Los presentados en día inhábil, que se tendrán por no presentados hasta el siguiente hábil", "Los presentados en las oficinas de Correos sin sello de fechas"]'::jsonb,0,'Art. 16.8 Ley 39/2015','No se tienen por presentados los que tengan un régimen especial con otra forma de presentación.',null),
('5-1fc174a8b8','aux-cm',5,'Como regla general, los actos administrativos se producirán:','["En papel con firma manuscrita del titular del órgano", "De la forma que elija el interesado en su solicitud, por escrito o verbalmente, en papel o electrónicamente", "Por escrito en papel, salvo que el interesado esté obligado a relacionarse electrónicamente", "Por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma"]'::jsonb,3,'Art. 36.1 Ley 39/2015','Se producen por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada.',null),
('6-dbad1fa7e5','aux-cm',6,'Cuando la Administración establezca expresamente modelos específicos de presentación de solicitudes en un procedimiento concreto, estos serán:','["De uso obligatorio por los interesados", "Solo orientativos", "Exclusivos para personas jurídicas", "De uso voluntario"]'::jsonb,0,'Art. 66.6 Ley 39/2015','Los modelos específicos establecidos expresamente son de uso obligatorio.',null),
('5-97837a63ae','aux-cm',5,'Las resoluciones administrativas de carácter particular no podrán vulnerar una disposición de carácter general:','["Aunque procedan de un órgano de igual o superior jerarquía al que dictó la disposición", "Salvo que lo autorice expresamente el Consejo de Ministros", "Salvo que procedan de un órgano de jerarquía superior al que dictó la disposición", "Salvo que sean favorables al interesado"]'::jsonb,0,'Art. 37.1 Ley 39/2015','Es el principio de inderogabilidad singular de los reglamentos.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('6-a95d72d7b5','aux-cm',6,'Los plazos expresados en días se contarán:','["Desde que el interesado tenga conocimiento efectivo del acto", "Desde el mismo día de la notificación o publicación del acto", "Desde el día en que se dictó el acto, aunque se notifique o publique con posterioridad a esa fecha", "A partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto"]'::jsonb,3,'Art. 30.3 Ley 39/2015','Se cuentan desde el día siguiente a la notificación o publicación.',null),
('1-a14c359129','aux-cm',1,'Las asociaciones solo pueden ser disueltas o suspendidas en sus actividades:','["Por orden del Ministerio del Interior", "Por acuerdo del Consejo de Ministros", "En virtud de resolución judicial motivada", "Por decisión de la Delegación del Gobierno"]'::jsonb,2,'Art. 22.4 CE','Solo podrán ser disueltas o suspendidas en virtud de resolución judicial motivada.',null),
('5-2668061146','aux-cm',5,'Según el art. 34.1 de la Ley 39/2015, los actos administrativos se producirán:','["Por el órgano competente, ajustándose a los requisitos y al procedimiento establecido", "Por el funcionario que tramite el expediente, con el visto bueno del titular del órgano", "Por cualquier órgano de la misma Administración", "Por el órgano competente, aunque no se ajusten al procedimiento establecido si el contenido es conforme a Derecho"]'::jsonb,0,'Art. 34.1 Ley 39/2015','Los actos se producen por el órgano competente ajustándose a los requisitos y al procedimiento establecido.',null),
('5-ceef5c76a0','aux-cm',5,'La obligación de notificar en plazo se entiende cumplida, en las notificaciones electrónicas, con:','["La puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única", "La publicación de un anuncio en el BOE", "El envío del aviso al correo electrónico del interesado, aunque no se ponga a disposición la notificación", "El acceso efectivo del interesado"]'::jsonb,0,'Art. 43.3 Ley 39/2015','Se entiende cumplida con la puesta a disposición en la sede electrónica o la dirección electrónica habilitada única.',null),
('5-f091761ac0','aux-cm',5,'¿A quién debe notificar el órgano que dicte una resolución?','["A los interesados cuyos derechos e intereses sean afectados por ella", "A todos los vecinos del municipio afectado", "Solo al solicitante, aunque haya otros interesados afectados", "Al superior jerárquico, que da traslado a los interesados"]'::jsonb,0,'Art. 40.1 Ley 39/2015','Se notifica a los interesados cuyos derechos e intereses sean afectados por las resoluciones y actos.',null),
('5-cdebe6e0dd','aux-cm',5,'La nulidad en parte de un acto no implica la de las partes independientes, salvo que:','["Se haya notificado conjuntamente y en un mismo documento a todos los interesados afectados", "Sea un acto favorable al interesado", "La parte viciada sea de tal importancia que sin ella el acto no se habría dictado", "Lo solicite el interesado en el recurso que interponga contra el acto, justificando su conexión"]'::jsonb,2,'Art. 49.2 Ley 39/2015','Las partes independientes se mantienen, salvo que la parte viciada fuera esencial.',null),
('1-3e68e48f06','aux-cm',1,'Según el art. 27.2, la educación tiene por objeto:','["El pleno desarrollo de la personalidad humana en el respeto a los principios democráticos y a los derechos fundamentales", "Preparar para el acceso al empleo y a la función pública", "La formación profesional exclusivamente", "El pleno desarrollo de la personalidad humana en el respeto a la religión mayoritaria y a las tradiciones de cada Comunidad Autónoma"]'::jsonb,0,'Art. 27.2 CE','Tiene por objeto el pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia y a los derechos y libertades fundamentales.',null),
('6-6661afb624','aux-cm',6,'En los procedimientos tramitados por la AGE, la lengua será:','["Siempre la lengua cooficial del territorio donde tenga su sede el órgano", "El castellano, sin que los interesados puedan utilizar ninguna otra lengua, aunque se dirijan a órganos con sede en una Comunidad Autónoma con lengua cooficial", "El castellano, aunque los interesados que se dirijan a órganos con sede en una Comunidad con lengua cooficial podrán utilizar también esta", "La que elija el funcionario que tramite el procedimiento, castellano o lengua cooficial, sin que el interesado pueda solicitar que se utilice otra"]'::jsonb,2,'Art. 15.1 Ley 39/2015','La lengua de la AGE es el castellano, con posibilidad de usar la cooficial ante órganos con sede en esa Comunidad.',null),
('4-90e5e3d6d6','aux-cm',4,'El Plan Anual Normativo que deben aprobar las Administraciones contiene:','["Los presupuestos y las normas fiscales del año siguiente", "Las iniciativas legales o reglamentarias que vayan a ser elevadas para su aprobación en el año siguiente", "Las iniciativas reglamentarias, pero no las legales, que se aprobarán en los cuatro años siguientes", "Las normas derogadas el año anterior"]'::jsonb,1,'Art. 132.1 Ley 39/2015','Se aprueba anualmente y se publica en el Portal de la Transparencia.',null),
('5-402b7f36e8','aux-cm',5,'Según el art. 47.1 f), son nulos los actos expresos o presuntos contrarios al ordenamiento por los que se adquieren facultades o derechos:','["Cuando no haya terceros afectados por la adquisición", "Cuando sean favorables al interesado y no haya terceros afectados por ellos", "Cuando se hayan publicado en el boletín oficial sin haberse notificado a los interesados", "Cuando se carezca de los requisitos esenciales para su adquisición"]'::jsonb,3,'Art. 47.1 f) Ley 39/2015','Son nulos si se adquieren facultades o derechos careciendo de los requisitos esenciales.',null),
('5-566cf0ebc6','aux-cm',5,'Si fueran varios los medios de ejecución admisibles, se elegirá:','["El más rápido para la Administración", "El que elija el interesado de entre los admisibles", "El más económico para la Administración actuante", "El menos restrictivo de la libertad individual"]'::jsonb,3,'Art. 100.2 Ley 39/2015','Se elige el menos restrictivo de la libertad individual.',null),
('6-3ee81be628','aux-cm',6,'Los poderes inscritos en el registro electrónico de apoderamientos tendrán una validez máxima de:','["Diez años a contar desde la fecha de inscripción", "Un año, renovable por periodos iguales", "Cinco años a contar desde la fecha de inscripción", "Indefinida, hasta su revocación"]'::jsonb,2,'Art. 6.6 Ley 39/2015','Validez máxima de cinco años; pueden revocarse o prorrogarse, la prórroga por un máximo de cinco años.',null),
('5-6e946a2a15','aux-cm',5,'Según el art. 105, no se admitirán a trámite contra las actuaciones de los órganos administrativos realizadas en materia de su competencia y de acuerdo con el procedimiento legal:','["Los recursos contencioso-administrativos", "Las acciones posesorias", "Los recursos de alzada", "Las reclamaciones de responsabilidad"]'::jsonb,1,'Art. 105 Ley 39/2015','No se admiten acciones posesorias contra esas actuaciones.',null),
('6-5b09ad2bb7','aux-cm',6,'De las solicitudes y escritos que presenten los interesados, estos podrán exigir:','["Una copia firmada por el titular del órgano destinatario", "La devolución de las tasas abonadas", "Una resolución inmediata sobre la admisión de la solicitud presentada", "El correspondiente recibo que acredite la fecha y hora de presentación"]'::jsonb,3,'Art. 66.3 Ley 39/2015','Pueden exigir recibo con fecha y hora de presentación.',null),
('1-da5b5caa94','aux-cm',1,'Según el art. 2, la Constitución se fundamenta en:','["La indisoluble unidad de la Nación española, y reconoce el derecho a la autonomía de las nacionalidades y regiones", "La voluntad del Jefe del Estado", "La soberanía compartida del Estado y de las Comunidades Autónomas, y reconoce su derecho a la autodeterminación", "El pacto entre los territorios históricos"]'::jsonb,0,'Art. 2 CE','Se fundamenta en la indisoluble unidad de la Nación española y reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones y la solidaridad entre todas ellas.','oct. 2026 · 1.er ejercicio'),
('1-dedb45996f','aux-cm',1,'¿Quién inspecciona y homologa el sistema educativo?','["Los poderes públicos", "Las universidades", "Los colegios profesionales", "Las asociaciones de padres"]'::jsonb,0,'Art. 27.8 CE','Los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.',null),
('6-b28df4a9d4','aux-cm',6,'La Administración aceptará de plano el desistimiento o la renuncia, salvo que terceros interesados personados insten la continuación en el plazo de:','["Cinco días desde que fueron notificados", "Un mes desde que fueron notificados", "Quince días desde que fueron notificados", "Diez días desde que fueron notificados"]'::jsonb,3,'Art. 94.4 Ley 39/2015','Los terceros tienen diez días para pedir la continuación.',null),
('5-6f91e18200','aux-cm',5,'Es nulo de pleno derecho el acto que:','["Lesione los derechos y libertades susceptibles de amparo constitucional", "Se dicte fuera del plazo establecido", "Tenga un defecto de forma que no produzca indefensión", "Incurra en desviación de poder o en cualquier otra infracción del ordenamiento"]'::jsonb,0,'Art. 47.1 a) Ley 39/2015','La lesión de derechos susceptibles de amparo es causa de nulidad de pleno derecho.',null),
('5-b5342ea664','aux-cm',5,'Si se trata de obligaciones personalísimas de hacer y no se realiza la prestación, el obligado deberá:','["Resarcir los daños y perjuicios, a cuya liquidación y cobro se procederá en vía administrativa", "Ser objeto de compulsión sobre su persona hasta que realice la prestación, sin resarcimiento alguno", "Nada, la obligación se extingue", "Resarcir los daños y perjuicios, cuya liquidación y cobro solo pueden exigirse en vía judicial civil"]'::jsonb,0,'Art. 104.2 Ley 39/2015','El obligado debe resarcir daños y perjuicios.',null),
('6-8d7e692054','aux-cm',6,'Contra el acuerdo que declare la tramitación de urgencia:','["No cabrá recurso alguno, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento", "Cabe recurso contencioso-administrativo inmediato", "Cabe recurso de alzada", "Cabe recurso potestativo de reposición en el plazo de un mes desde su notificación, que no suspende la tramitación"]'::jsonb,0,'Art. 33.2 Ley 39/2015','El acuerdo de urgencia no es recurrible.',null),
('6-b4b364b9dc','aux-cm',6,'Con anterioridad al inicio del procedimiento, el órgano competente podrá abrir:','["El período de prueba", "Un período de información o actuaciones previas para conocer las circunstancias del caso y la conveniencia de iniciar", "El trámite de audiencia a los posibles interesados para que aleguen sobre la conveniencia de iniciar el procedimiento", "El trámite de información pública"]'::jsonb,1,'Art. 55.1 Ley 39/2015','Las actuaciones previas sirven para valorar si procede iniciar el procedimiento.',null),
('5-2fa0e359e3','aux-cm',5,'El órgano competente podrá inadmitir sin dictamen las solicitudes de revisión de oficio formuladas por interesados cuando:','["Se refieran a actos favorables", "Sean formuladas por personas jurídicas", "Se presenten en papel", "Carezcan manifiestamente de fundamento"]'::jsonb,3,'Art. 106.3 Ley 39/2015','También cuando no se basen en causas de nulidad o se hayan desestimado en cuanto al fondo otras sustancialmente iguales.','nov. 2024 · 1.er ejercicio'),
('1-8b58d7aca7','aux-cm',1,'Según el art. 41, los poderes públicos mantendrán:','["Mutualidades profesionales obligatorias", "Un seguro médico solo para los trabajadores por cuenta ajena", "Un sistema privado de pensiones obligatorio", "Un régimen público de Seguridad Social para todos los ciudadanos"]'::jsonb,3,'Art. 41 CE','Mantendrán un régimen público de Seguridad Social para todos los ciudadanos.',null),
('5-d00dcb5388','aux-cm',5,'Si en la notificación en papel en el domicilio el interesado no está presente, podrá hacerse cargo de ella:','["Solo un familiar mayor de 18 años", "Cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad", "Cualquier persona mayor de 16 años que se encuentre en el domicilio, sin necesidad de hacer constar su identidad", "Únicamente el interesado"]'::jsonb,1,'Art. 42.2 Ley 39/2015','Puede recogerla cualquier persona mayor de catorce años que esté en el domicilio y haga constar su identidad.',null),
('1-fe54ba37e8','aux-cm',1,'Según el art. 39.1, los poderes públicos aseguran:','["Una vivienda digna a cada familia", "La protección social, económica y jurídica de la familia", "La protección social, económica y jurídica de la familia, pero solo de la fundada en el matrimonio", "La educación obligatoria hasta los 25 años"]'::jsonb,1,'Art. 39.1 CE','Los poderes públicos aseguran la protección social, económica y jurídica de la familia.','nov. 2024 · 1.er ejercicio'),
('5-e00c2cb268','aux-cm',5,'¿Cuál de las siguientes NO es causa de inadmisión del art. 116?','["Tratarse de un acto no susceptible de recurso", "Carecer de legitimación el recurrente", "Carecer el recurso manifiestamente de fundamento", "Que el recurso se haya calificado erróneamente"]'::jsonb,3,'Art. 116 Ley 39/2015','El error en la calificación no impide la tramitación (art. 115.2).',null),
('1-24e35cd45b','aux-cm',1,'Según el art. 50, los poderes públicos garantizarán a los ciudadanos durante la tercera edad:','["Una plaza en una residencia pública", "La gratuidad del transporte público", "Una pensión igual para todos, independientemente de lo cotizado", "Pensiones adecuadas y periódicamente actualizadas"]'::jsonb,3,'Art. 50 CE','Garantizarán, mediante pensiones adecuadas y periódicamente actualizadas, la suficiencia económica en la tercera edad.',null),
('5-26739c587b','aux-cm',5,'Las facultades de revisión no podrán ejercerse cuando:','["Lo solicite el propio interesado", "El acto sea nulo de pleno derecho", "Por prescripción de acciones, tiempo transcurrido u otras circunstancias, su ejercicio resulte contrario a la equidad, la buena fe, el derecho de los particulares o las leyes", "Haya transcurrido un año desde la notificación del acto, cualquiera que sea el vicio que lo afecte y aunque su ejercicio no resulte contrario a la equidad, la buena fe ni el derecho de los particulares"]'::jsonb,2,'Art. 110 Ley 39/2015','Son los límites de la revisión.',null),
('4-c2252350d8','aux-cm',4,'Según el art. 128.3 de la Ley 39/2015, las disposiciones administrativas:','["Se ajustarán al orden de jerarquía y ninguna podrá vulnerar los preceptos de otra de rango superior", "Tienen todas el mismo rango, y prevalece la posterior", "Prevalecen sobre las leyes", "Se ajustarán al orden de jerarquía, salvo que la de rango inferior sea posterior en el tiempo y regule una materia más específica"]'::jsonb,0,'Art. 128.3 Ley 39/2015','Principio de jerarquía normativa.',null),
('1-805bfafd54','aux-cm',1,'El sistema tributario, según el art. 31.1, debe ser justo, inspirado en la igualdad y la progresividad, y:','["Proporcional a la renta en todo caso", "Igual para todos los contribuyentes, con independencia de su renta", "En ningún caso tendrá alcance confiscatorio", "Exclusivamente estatal"]'::jsonb,2,'Art. 31.1 CE','Se basa en la igualdad y la progresividad, y en ningún caso tendrá alcance confiscatorio.',null),
('1-41e8284645','aux-cm',1,'Se reconoce a las personas físicas y jurídicas la libertad de:','["Expedir títulos oficiales sin necesidad de homologación", "Fijar libremente los planes de estudio oficiales", "Creación de centros docentes, dentro del respeto a los principios constitucionales", "Creación de centros docentes, que solo podrán impartir enseñanzas no regladas"]'::jsonb,2,'Art. 27.6 CE','Se reconoce la libertad de creación de centros docentes, dentro del respeto a los principios constitucionales.',null),
('6-d0857b3b1c','aux-cm',6,'En el procedimiento sancionador, el órgano instructor resolverá la finalización con archivo de actuaciones, sin formular propuesta de resolución, cuando:','["La sanción que corresponda sea muy grave", "El denunciante lo solicite expresamente y retire la denuncia antes de la propuesta de resolución", "Los hechos probados no constituyan, de modo manifiesto, infracción administrativa", "El presunto infractor reconozca su responsabilidad y pague voluntariamente la sanción"]'::jsonb,2,'Art. 89.1 c) Ley 39/2015','También por inexistencia de los hechos, falta de prueba, falta de responsable o prescripción de la infracción.',null),
('5-c42453ed59','aux-cm',5,'Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este. Esto se denomina:','["Revocación", "Conservación de actos y trámites", "Convalidación", "Conversión de actos viciados"]'::jsonb,3,'Art. 50 Ley 39/2015','Es la conversión de actos viciados.','oct. 2026 · 1.er ejercicio'),
('6-79f5268e7f','aux-cm',6,'Las Administraciones deben publicar y mantener actualizadas en el portal web:','["Las nóminas de todos sus empleados", "Las resoluciones judiciales que les afecten", "Las relaciones de procedimientos de su competencia, con indicación de los plazos máximos de duración y de los efectos del silencio administrativo", "Las relaciones de procedimientos de su competencia, con los datos de los interesados y el estado de tramitación de cada expediente"]'::jsonb,2,'Art. 21.4 Ley 39/2015','Deben publicar los procedimientos, sus plazos máximos y los efectos del silencio.',null),
('6-4b9e998b2f','aux-cm',6,'Transcurridos seis meses desde el inicio de un procedimiento de responsabilidad patrimonial sin resolución ni acuerdo:','["El procedimiento caduca y se archivan las actuaciones sin pronunciamiento sobre la indemnización", "Se entiende estimada la reclamación", "Se paga automáticamente la indemnización", "Podrá entenderse que la resolución es contraria a la indemnización del particular"]'::jsonb,3,'Art. 91.3 Ley 39/2015','El silencio en responsabilidad patrimonial es desestimatorio.',null),
('6-61584b97bc','aux-cm',6,'Las medidas provisionales adoptadas antes de iniciar el procedimiento deberán ser confirmadas, modificadas o levantadas en el acuerdo de iniciación, que deberá efectuarse:','["Dentro del mes siguiente a su adopción", "Dentro de los tres meses siguientes", "Dentro de los quince días siguientes a su adopción", "Dentro de los diez días siguientes a su adopción"]'::jsonb,2,'Art. 56.2 Ley 39/2015','Si no se inicia en ese plazo o el acuerdo no se pronuncia, las medidas quedan sin efecto.','oct. 2026 · 1.er ejercicio'),
('6-399720ca1d','aux-cm',6,'Los documentos formalizados por funcionarios con la condición de autoridad en los que se recojan hechos constatados por ellos:','["Tienen valor absoluto e irrebatible", "Solo tienen valor probatorio si los ratifica un juez o el instructor del procedimiento", "No tienen valor probatorio", "Harán prueba de estos salvo que se acredite lo contrario"]'::jsonb,3,'Art. 77.5 Ley 39/2015','Gozan de presunción de veracidad salvo prueba en contrario.',null),
('6-3a84dff6e5','aux-cm',6,'Salvo que reste menos para su tramitación ordinaria, los procedimientos de tramitación simplificada deberán resolverse en:','["Tres meses desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Seis meses desde el inicio del procedimiento", "Treinta días desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Quince días desde el siguiente al que se notifique el acuerdo de tramitación simplificada"]'::jsonb,2,'Art. 96.6 Ley 39/2015','El plazo es de treinta días.',null),
('6-505acd6f0f','aux-cm',6,'Se entiende por propia iniciativa:','["La petición de un órgano sin competencia de iniciación", "La denuncia de un particular que pone los hechos en conocimiento del órgano competente para iniciar, sin que este tenga conocimiento directo de las circunstancias", "La actuación derivada del conocimiento directo o indirecto de las circunstancias o hechos por el órgano que tiene la competencia de iniciación", "La orden emitida por un órgano superior jerárquico del competente para iniciar, tras conocer los hechos por una denuncia o por una petición razonada de otro órgano"]'::jsonb,2,'Art. 59 Ley 39/2015','Es el conocimiento directo o indirecto por el propio órgano competente.',null),
('6-b2ddcbe44b','aux-cm',6,'En la resolución del procedimiento sancionador no se podrán aceptar hechos distintos de los determinados en el curso del procedimiento:','["Salvo que resulten más graves, en cuyo caso se notificarán al inculpado para que formule alegaciones", "Salvo en las infracciones leves, en las que sí pueden aceptarse", "Salvo que lo pida el denunciante", "Con independencia de su diferente valoración jurídica"]'::jsonb,3,'Art. 90.2 Ley 39/2015','Se protege el derecho de defensa del inculpado.',null),
('1-da8d51d11d','aux-cm',1,'Según el art. 9.2, corresponde a los poderes públicos:','["Promover las condiciones para que la libertad y la igualdad sean reales y efectivas, y remover los obstáculos que lo impidan", "Regular la vida privada de los ciudadanos", "Limitar la participación política", "Garantizar la igualdad de resultados económicos entre todos los ciudadanos y territorios, y suprimir las diferencias de renta que lo impidan"]'::jsonb,0,'Art. 9.2 CE','Deben promover esas condiciones, remover los obstáculos y facilitar la participación de todos los ciudadanos.',null),
('6-34317bc82e','aux-cm',6,'En el procedimiento de responsabilidad patrimonial iniciado de oficio, el acuerdo de iniciación se notificará a los presuntos lesionados, concediéndoles un plazo para alegaciones y pruebas de:','["Un mes", "Cinco días", "Diez días", "Quince días"]'::jsonb,2,'Art. 65.2 Ley 39/2015','Se les concede diez días para aportar alegaciones, documentos o información y proponer pruebas.',null),
('1-7911f44274','aux-cm',1,'¿Qué regula la ley según el art. 30.2?','["El servicio militar obligatorio, su duración y las causas de exención", "El ejército profesional exclusivamente", "La participación de España en organizaciones internacionales de defensa", "Las obligaciones militares de los españoles y la objeción de conciencia"]'::jsonb,3,'Art. 30.2 CE','La ley fijará las obligaciones militares de los españoles y regulará la objeción de conciencia.',null),
('6-fdd873cd08','aux-cm',6,'Según el art. 1.2, solo podrán incluirse trámites adicionales o distintos de los de la Ley 39/2015:','["Mediante circular o instrucción interna", "Por decisión del órgano instructor", "Mediante reglamento, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento", "Mediante ley, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento"]'::jsonb,3,'Art. 1.2 Ley 39/2015','Solo mediante ley y de forma motivada.',null),
('5-7e6c4c622e','aux-cm',5,'Es nulo de pleno derecho el acto:','["Que incurra en cualquier infracción del ordenamiento jurídico, incluida la desviación de poder", "Cuyo defecto de forma no produzca indefensión", "Que sea constitutivo de infracción penal o se dicte como consecuencia de esta", "Dictado un día inhábil"]'::jsonb,2,'Art. 47.1 d) Ley 39/2015','Los actos constitutivos de infracción penal o dictados como consecuencia de esta son nulos.',null),
('1-ed1eb93c87','aux-cm',1,'Según el art. 42, el Estado orientará su política hacia el retorno de:','["Los trabajadores españoles en el extranjero", "Los capitales invertidos fuera", "Los funcionarios destinados en el exterior", "Los estudiantes de Erasmus"]'::jsonb,0,'Art. 42 CE','El Estado velará por los derechos de los trabajadores españoles en el extranjero y orientará su política hacia su retorno.',null),
('6-9230c5037e','aux-cm',6,'En los procedimientos tramitados a solicitud del interesado, la resolución será congruente con las peticiones formuladas:','["Solo si el instructor lo propone y el interesado no se opone", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Salvo que sea una persona jurídica", "Sin que en ningún caso pueda agravar su situación inicial"]'::jsonb,3,'Art. 88.2 Ley 39/2015','Sin perjuicio de la potestad de incoar de oficio un nuevo procedimiento.',null),
('6-7ad12d7fbe','aux-cm',6,'La presentación de una denuncia:','["Convierte al denunciante en interesado en el procedimiento sancionador que se inicie", "Obliga a iniciar el procedimiento y a sancionar", "No confiere, por sí sola, la condición de interesado en el procedimiento", "Requiere asistencia de abogado"]'::jsonb,2,'Art. 62.5 Ley 39/2015','El denunciante no es interesado por el solo hecho de denunciar.',null),
('6-c90baee743','aux-cm',6,'Según el art. 62.1, se entiende por denuncia:','["La solicitud de un interesado para que se inicie un procedimiento en su favor", "El acto por el que cualquier persona, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo un hecho que pudiera justificar la iniciación de oficio", "La propuesta de iniciación formulada por un órgano administrativo sin competencia para iniciar, que tiene conocimiento de los hechos por razón de sus funciones de inspección, averiguación o investigación", "La orden de un superior"]'::jsonb,1,'Art. 62.1 Ley 39/2015','Definición legal de la denuncia.',null),
('5-c4a1d9234e','aux-cm',5,'Si existe vicio de forma y no se estima procedente resolver sobre el fondo, el órgano que resuelve el recurso:','["Dictará resolución favorable", "Inadmitirá el recurso", "Ordenará la retroacción del procedimiento al momento en que el vicio fue cometido", "Anulará todo el expediente y ordenará iniciar uno nuevo desde el principio"]'::jsonb,2,'Art. 119.2 Ley 39/2015','Se ordena retrotraer el procedimiento al momento del vicio.',null),
('6-f02b3988fa','aux-cm',6,'En los procedimientos de responsabilidad patrimonial ante la AGE, es preceptivo el dictamen del Consejo de Estado cuando la indemnización reclamada sea de cuantía igual o superior a:','["50.000 euros", "6.000 euros", "100.000 euros", "30.000 euros"]'::jsonb,0,'Art. 81.2 Ley 39/2015','Desde 50.000 € (o la cuantía fijada por la legislación autonómica) es preceptivo el dictamen.',null),
('5-481150f0da','aux-cm',5,'Cuando deban resolverse una pluralidad de recursos derivados de un mismo acto y se haya interpuesto recurso judicial contra una resolución administrativa o contra el correspondiente acto presunto:','["El órgano administrativo podrá acordar la suspensión del plazo para resolver hasta que recaiga pronunciamiento judicial", "Deberá inadmitir todos los recursos pendientes", "Deberá estimar todos los recursos", "Deberá resolver todos los recursos en el plazo ordinario, sin esperar al pronunciamiento judicial, para no perjudicar a los interesados que no han acudido a los tribunales"]'::jsonb,0,'Art. 120.1 Ley 39/2015','El órgano puede suspender el plazo hasta que haya pronunciamiento judicial.',null),
('6-e8154c7a93','aux-cm',6,'En el despacho de los expedientes se guardará:','["El orden que prefiera el funcionario responsable", "El orden alfabético de los interesados, salvo orden motivada en contrario del superior jerárquico del instructor", "El orden riguroso de incoación en asuntos de homogénea naturaleza, salvo orden motivada en contrario", "El orden de prioridad que fije cada interesado en su solicitud, o el que indique el superior jerárquico en cada caso concreto"]'::jsonb,2,'Art. 71.2 Ley 39/2015','Su incumplimiento puede dar lugar a responsabilidad disciplinaria.',null),
('5-361a7d1e7f','aux-cm',5,'El órgano que ordene un acto de ejecución material de resoluciones está obligado a:','["Publicarlo en el BOE y en el boletín autonómico antes de iniciar la actuación material, sin necesidad de notificación personal", "Solicitar autorización judicial", "Esperar a que el acto sea firme en vía administrativa y solicitar autorización judicial para ejecutarlo", "Notificar al particular interesado la resolución que autorice la actuación administrativa"]'::jsonb,3,'Art. 97.2 Ley 39/2015','Debe notificar al particular la resolución que autorice la actuación.',null),
('1-e78cb61d7c','aux-cm',1,'El contenido del derecho de propiedad y de herencia lo delimita:','["Las ordenanzas fiscales de cada municipio", "La voluntad del propietario", "Su función social, de acuerdo con las leyes", "El Registro de la Propiedad"]'::jsonb,2,'Art. 33.2 CE','La función social de estos derechos delimitará su contenido, de acuerdo con las leyes.',null),
('5-5c7654841e','aux-cm',5,'El recurso extraordinario de revisión se interpone contra:','["Los actos que no ponen fin a la vía administrativa, en cualquier momento", "Los actos firmes en vía administrativa, cuando concurra alguna de las circunstancias del art. 125.1", "Cualquier acto de trámite", "Las disposiciones de carácter general, cuando concurra alguna de las circunstancias del art. 125.1"]'::jsonb,1,'Art. 113 Ley 39/2015','Procede contra actos firmes en vía administrativa en los casos del art. 125.1.',null),
('6-e7733c33b2','aux-cm',6,'NO forma parte del expediente administrativo:','["La información auxiliar o de apoyo, como notas, borradores u opiniones, salvo los informes solicitados antes de la resolución", "Las notificaciones practicadas", "Las pruebas practicadas", "Los informes preceptivos, que se incorporan a un expediente auxiliar distinto del principal y no se remiten al juzgado"]'::jsonb,0,'Art. 70.4 Ley 39/2015','Notas, borradores, opiniones, resúmenes y comunicaciones internas no forman parte del expediente.',null),
('1-f2bcc0328a','aux-cm',1,'Según el art. 23.1, los ciudadanos participan en los asuntos públicos:','["Solo por medio de los partidos políticos con representación parlamentaria", "Directamente o por medio de representantes elegidos en elecciones periódicas por sufragio censitario", "Por medio de representantes designados por las Cortes Generales y por los Parlamentos autonómicos", "Directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal"]'::jsonb,3,'Art. 23.1 CE','Participan directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal.',null),
('6-939b33705d','aux-cm',6,'Las declaraciones responsables y las comunicaciones permiten el reconocimiento o ejercicio de un derecho o el inicio de una actividad:','["Tras la resolución expresa que reconozca el derecho, que deberá dictarse en un mes", "A los tres meses de su presentación si la Administración no se opone", "Desde el día de su presentación, sin perjuicio de las facultades de comprobación de la Administración", "Desde el día de su presentación, sin que la Administración pueda comprobar después lo declarado"]'::jsonb,2,'Art. 69.3 Ley 39/2015','Producen efectos desde su presentación.',null),
('1-67b307c0a0','aux-cm',1,'Las bases de la organización militar se regulan mediante:','["Un real decreto", "Una ley ordinaria", "Una ley orgánica", "Una orden del Ministerio de Defensa"]'::jsonb,2,'Art. 8.2 CE','Una ley orgánica regulará las bases de la organización militar.',null),
('1-3832bbafdc','aux-cm',1,'Según el art. 51.1, los poderes públicos garantizarán la defensa de:','["Los consumidores y usuarios, protegiendo mediante procedimientos eficaces su seguridad, salud e intereses económicos", "Los comerciantes minoristas exclusivamente", "Las empresas frente a la competencia desleal y los productores frente a las importaciones de terceros países", "Los productores agrarios"]'::jsonb,0,'Art. 51.1 CE','Garantizarán la defensa de los consumidores y usuarios mediante procedimientos eficaces.',null),
('6-c020b0f464','aux-cm',6,'Si el escrito de iniciación se formuló por dos o más interesados, el desistimiento o la renuncia:','["No está permitido una vez iniciado el procedimiento", "Requiere el acuerdo unánime de todos los que firmaron el escrito de iniciación", "Solo afectará a aquellos que la hubiesen formulado", "Afectará a todos los interesados, salvo que alguno inste la continuación en diez días"]'::jsonb,2,'Art. 94.2 Ley 39/2015','El desistimiento solo afecta a quien lo formula.',null),
('5-9ff0600d6a','aux-cm',5,'Es causa del recurso extraordinario de revisión:','["Que haya transcurrido el plazo para interponer el recurso de alzada sin haberlo hecho, por causa no imputable al interesado", "Que el interesado cambie de opinión", "Que el acto sea desfavorable y el interesado aporte cualquier documento nuevo, aunque no evidencie error alguno en la resolución", "Que aparezcan documentos de valor esencial para la resolución que evidencien el error de la resolución recurrida"]'::jsonb,3,'Art. 125.1 b) Ley 39/2015','Las causas son: error de hecho, documentos esenciales nuevos, documentos o testimonios falsos declarados en sentencia firme y conducta punible declarada en sentencia firme.',null),
('5-c95b769593','aux-cm',5,'La declaración de lesividad de los actos favorables anulables tiene como finalidad:','["Sancionar al interesado que se benefició del acto", "Convertirlos en actos nulos de pleno derecho para poder revisarlos de oficio en cualquier momento", "Su posterior impugnación ante el orden jurisdiccional contencioso-administrativo", "Anularlos directamente en vía administrativa"]'::jsonb,2,'Art. 107.1 Ley 39/2015','La Administración declara la lesividad para impugnarlos después ante la jurisdicción contencioso-administrativa.',null),
('6-e697f57bd5','aux-cm',6,'Para los actos y gestiones de mero trámite, la representación:','["No está permitida", "Se presumirá", "Debe acreditarse ante notario", "Debe inscribirse en el registro de apoderamientos"]'::jsonb,1,'Art. 5.3 Ley 39/2015','En los actos de mero trámite se presume la representación.',null),
('4-42d5e9626a','aux-cm',4,'Según el art. 130.1, las Administraciones Públicas revisarán periódicamente su normativa vigente para:','["Derogarla cada cuatro años y aprobar textos refundidos", "Remitirla al Tribunal Constitucional para que verifique su adecuación a la Constitución y a los Estatutos de Autonomía", "Adaptarla a los principios de buena regulación, sin necesidad de evaluar si ha conseguido sus objetivos", "Adaptarla a los principios de buena regulación y comprobar en qué medida han conseguido sus objetivos"]'::jsonb,3,'Art. 130.1 Ley 39/2015','El resultado de la evaluación se plasma en un informe que se hará público.',null),
('1-59212fd71c','aux-cm',1,'En el control y la gestión de los centros sostenidos con fondos públicos intervienen:','["Solo la Administración educativa competente", "Los sindicatos más representativos y la Administración", "Solo el director del centro y el titular, en el caso de los centros concertados", "Los profesores, los padres y, en su caso, los alumnos"]'::jsonb,3,'Art. 27.7 CE','Intervienen los profesores, los padres y, en su caso, los alumnos, en los términos que la ley establezca.',null),
('5-14077e427c','aux-cm',5,'Son nulos de pleno derecho los actos:','["Dictados por órgano jerárquicamente incompetente", "Que tengan un contenido imposible", "Que no indiquen los recursos", "Que tengan un error material"]'::jsonb,1,'Art. 47.1 c) Ley 39/2015','El contenido imposible es causa de nulidad (art. 47.1 c).',null),
('1-df3e9acaf2','aux-cm',1,'Según el art. 19, los españoles tienen derecho a:','["Una vivienda pública en su lugar de residencia", "Cambiar de nacionalidad libremente y entrar y salir de España sin requisitos", "Viajar sin pasaporte a cualquier país y residir en el extranjero sin requisitos", "Elegir libremente su residencia y a circular por el territorio nacional"]'::jsonb,3,'Art. 19 CE','Tienen derecho a elegir libremente su residencia y a circular por el territorio nacional.',null),
('11-e64b7bed94','aux-cm',11,'La pensión de viudedad de un causante en alta exige, con carácter general, un periodo de cotización de:','["Quinientos días dentro de un periodo ininterrumpido de cinco años inmediatamente anteriores al hecho causante", "Ninguno, si el causante estaba en alta", "Quinientos días dentro de un periodo ininterrumpido de diez años inmediatamente anteriores al hecho causante", "Quince años, de los cuales al menos dos en los últimos quince"]'::jsonb,0,'Art. 219.1 TRLGSS','Si el causante no estaba en alta ni en situación asimilada, se exigen quince años.',null),
('11-49705c5969','aux-cm',11,'La gestión de las pensiones no contributivas de invalidez y jubilación corresponde a:','["El INGESA", "La TGSS", "El INSS", "El IMSERSO"]'::jsonb,3,'Art. 66.1 c) TRLGSS','El INSS gestiona las prestaciones económicas del sistema, salvo las del IMSERSO.',null),
('11-fdb95358b8','aux-cm',11,'En la jubilación parcial, la reducción de la jornada debe estar comprendida entre:','["Un mínimo del 10 % y un máximo del 50 %", "Un mínimo del 30 % y un máximo del 60 %", "Un mínimo del 25 % y un máximo del 75 %", "Un mínimo del 50 % y un máximo del 90 %"]'::jsonb,2,'Art. 215.1 TRLGSS','Según el art. 215 en su redacción consolidada.',null),
('10-76bd17a353','aux-cm',10,'Las retribuciones básicas están integradas por:','["La productividad y las gratificaciones por servicios extraordinarios", "El sueldo asignado a cada subgrupo o grupo y los trienios", "El complemento de destino y el complemento específico", "El sueldo asignado a cada subgrupo, los trienios y el complemento de destino del puesto que se ocupe"]'::jsonb,1,'Art. 23 TREBEP','Los trienios consisten en una cantidad por cada tres años de servicio.','abr. 2026 · 1.er ejercicio'),
('10-52016e83fc','aux-cm',10,'Los Delegados de Personal representan a los funcionarios en unidades electorales que cuenten con:','["Más de 50 funcionarios", "Menos de 6 funcionarios", "Entre 6 y 49 funcionarios", "Más de 250 funcionarios"]'::jsonb,2,'Art. 39.2 TREBEP','A partir de 50 funcionarios hay Juntas de Personal.',null),
('11-b83906a562','aux-cm',11,'Según el art. 137 TRLGSS, NO dan lugar a inclusión en el Régimen General:','["Los trabajos por cuenta ajena de carácter temporal", "Los funcionarios incluidos por ley", "Los trabajos ocasionales realizados por servicios amistosos, benévolos o de buena vecindad", "Los socios trabajadores de cooperativas asimilados por ley a trabajadores por cuenta ajena"]'::jsonb,2,'Art. 137 a) TRLGSS','Es una de las exclusiones del Régimen General.',null),
('9-37734049cf','aux-cm',9,'En la tramitación urgente del expediente, el plazo de inicio de la ejecución del contrato no podrá exceder de:','["Quince días, contados desde la formalización", "Tres meses, contados desde la adjudicación", "Una semana, contada desde la formalización", "Un mes, contado desde la formalización"]'::jsonb,3,'Art. 119.2 c) LCSP','La urgencia reduce además a la mitad los plazos de licitación, adjudicación y formalización.',null),
('11-d6f21417d3','aux-cm',11,'Con carácter general, la edad ordinaria de jubilación es de 67 años, o de 65 años cuando se acrediten:','["40 años de cotización", "38 años y 6 meses de cotización", "35 años de cotización", "36 años y 6 meses de cotización"]'::jsonb,1,'Art. 205.1 a) TRLGSS','Según el texto consolidado del TRLGSS en el BOE.',null),
('7-b6dfe5fbca','aux-cm',7,'El recurso de casación podrá ser admitido cuando presente:','["Interés casacional objetivo para la formación de jurisprudencia", "La conformidad de ambas partes", "Una cuantía superior a 600.000 euros, sin necesidad de interés casacional", "Un error de hecho del juez"]'::jsonb,0,'Art. 88.1 Ley 29/1998','La admisión se basa en el interés casacional objetivo.',null),
('9-2669af9216','aux-cm',9,'El orden jurisdiccional contencioso-administrativo es competente para resolver las cuestiones relativas a:','["Los delitos cometidos por el contratista en la ejecución", "Los efectos y extinción de los contratos privados de los poderes adjudicadores que no sean Administraciones", "La preparación, adjudicación, efectos, modificación y extinción de los contratos administrativos", "Los despidos del personal del contratista y las reclamaciones de los subcontratistas por los pagos pendientes"]'::jsonb,2,'Art. 27.1 a) LCSP','El orden civil conoce de los efectos y extinción de los contratos privados.',null),
('10-531a5572b8','aux-cm',10,'El plazo de prescripción de las sanciones comenzará a contarse:','["Desde la firmeza de la resolución sancionadora", "Desde la notificación del pliego de cargos", "Desde la incoación del expediente", "Desde la comisión de la falta"]'::jsonb,0,'Art. 97 TREBEP','El de las faltas, desde que se hubieran cometido, o desde el cese de su comisión si son continuadas.',null),
('9-a11eace1b0','aux-cm',9,'Es causa de resolución del contrato la demora en el cumplimiento de los plazos que suponga un retraso injustificado superior a:','["La mitad del plazo de duración inicial del contrato", "Un mes, en todo caso", "Un quinto del plazo de duración inicial del contrato, sin incluir las prórrogas", "Un tercio del plazo de duración inicial del contrato, incluidas las prórrogas"]'::jsonb,3,'Art. 211.1 d) LCSP','Es una de las causas de resolución del art. 211.',null),
('10-cbe2105134','aux-cm',10,'El personal eventual:','["Tiene derecho a la inamovilidad tras dos años de servicio, y su nombramiento corresponde al órgano de selección tras un concurso de méritos con convocatoria pública", "Ocupa puestos reservados a funcionarios de carrera", "Solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, y su nombramiento y cese son libres", "Accede mediante concurso de méritos"]'::jsonb,2,'Art. 12.1 y 12.3 TREBEP','El cese tiene lugar, en todo caso, cuando se produzca el de la autoridad a la que preste su función de confianza.',null),
('11-eaea16a5a7','aux-cm',11,'La prestación por riesgo durante el embarazo consiste en un subsidio equivalente al:','["50 % de la base reguladora de contingencias comunes", "100 % de la base reguladora de la incapacidad temporal derivada de contingencias profesionales", "75 % de la base reguladora de la incapacidad temporal derivada de contingencias comunes", "60 % de la base"]'::jsonb,1,'Art. 187.3 TRLGSS','Se trata como contingencia profesional.',null),
('14-454e12c585','aux-cm',14,'Las sugerencias y reclamaciones deberán formularse:','["Por teléfono exclusivamente", "De forma anónima, para proteger al reclamante, a través del buzón habilitado en cada oficina, sin necesidad de identificar el objeto de la reclamación ni al reclamante", "Por escrito, con los datos que permitan identificar y localizar al reclamante y el objeto de la sugerencia o reclamación", "De forma presencial en la oficina afectada"]'::jsonb,2,'Art. 30.1 Decreto 21/2002 CM','Pueden presentarse en los lugares del art. 16, por fax o por Internet.',null),
('10-eeee1096cf','aux-cm',10,'Según el art. 54.11, los empleados públicos garantizarán la atención al ciudadano en:','["La lengua oficial que solicite y, si lo pide, también en inglés", "Castellano exclusivamente", "La lengua que lo solicite siempre que sea oficial en el territorio", "La lengua que elija el funcionario"]'::jsonb,2,'Art. 54.11 TREBEP','Es otro principio de conducta.',null),
('9-235dfa7bbd','aux-cm',9,'Un encargo a un medio propio personificado que cumpla los requisitos legales:','["Es un contrato menor, si no supera los 15.000 euros", "Es un contrato de servicios no armonizado", "Requiere licitación pública", "No tendrá la consideración de contrato"]'::jsonb,3,'Art. 32.1 LCSP','Requiere, entre otros, que más del 80 % de la actividad del ente se realice para el poder adjudicador que lo controla.',null),
('13-50fb386699','aux-cm',13,'El Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado se aprueba por el Gobierno:','["Cada diez años", "Cada año", "Solo cuando lo pide el Congreso", "Al inicio de cada legislatura"]'::jsonb,3,'Art. 64 LO 3/2007','Su cumplimiento se evalúa anualmente por el Consejo de Ministros.',null),
('7-9f27ca24db','aux-cm',7,'Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia conocen en segunda instancia de:','["Los recursos contra actos de los Ministros y Secretarios de Estado", "Los recursos de casación autonómicos", "Los recursos contra actos del Consejo de Ministros y de las Comisiones Delegadas del Gobierno", "Los recursos de apelación contra sentencias y autos de los Juzgados de lo Contencioso-administrativo"]'::jsonb,3,'Art. 10.2 Ley 29/1998','En única instancia conocen, entre otros, de las disposiciones generales autonómicas y locales. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('7-f2f3fbacec','aux-cm',7,'El recurso de casación se preparará ante la Sala que dictó la resolución recurrida en el plazo de:','["Dos meses desde su notificación", "Quince días desde su notificación", "Treinta días desde su notificación", "Diez días desde su notificación"]'::jsonb,2,'Art. 89.1 Ley 29/1998','La casación se prepara en treinta días.',null),
('10-63ca7cd705','aux-cm',10,'En las ofertas de empleo público se reservará un cupo para personas con discapacidad no inferior al:','["2 % de las vacantes", "5 % de las vacantes", "10 % de las vacantes", "7 % de las vacantes"]'::jsonb,3,'Art. 59.1 TREBEP','De ese cupo, al menos el 2 % de las plazas para personas con discapacidad intelectual.',null),
('10-e3e4bb1940','aux-cm',10,'Por traslado de domicilio sin cambio de residencia, el funcionario tiene un permiso de:','["Ningún día", "Dos días", "Un día", "Tres días"]'::jsonb,2,'Art. 48 b) TREBEP','Permiso de un día por traslado de domicilio.',null),
('13-18218d0998','aux-cm',13,'Según la LO 1/2004, la víctima de violencia de género tiene derecho a recibir asesoramiento jurídico gratuito:','["Solo si es funcionaria o empleada pública", "Solo después de que recaiga sentencia condenatoria firme contra el agresor", "En el momento inmediatamente previo a la interposición de la denuncia", "Solo si tiene hijos menores a su cargo"]'::jsonb,2,'Art. 20.1 LO 1/2004','También tienen derecho a defensa y representación gratuitas.',null),
('14-33cf512bc7','aux-cm',14,'La información general versa, entre otros aspectos, sobre:','["Las deliberaciones internas del Consejo de Gobierno", "El estado de tramitación de un expediente concreto, la identidad del personal responsable y los datos de los demás interesados en el procedimiento, dirigida a cualquier ciudadano que la pida", "Los datos personales de otros interesados, el estado de tramitación de sus expedientes y la identidad de las autoridades responsables, a petición de cualquiera", "Los fines, competencias y funcionamiento de los órganos y servicios, la localización y horarios de las oficinas y los trámites y documentación exigidos"]'::jsonb,3,'Art. 7.1 Decreto 21/2002 CM','La información sobre un expediente concreto es información particular.',null),
('7-e5ba87c044','aux-cm',7,'Según el art. 19.1 h), cualquier ciudadano puede actuar ante la jurisdicción contencioso-administrativa:','["Mediante la acción popular, en los casos expresamente previstos por las leyes", "Solo si es funcionario o acredita un interés legítimo directo y personal en el asunto", "Solo a través del Defensor del Pueblo", "Mediante la acción popular, en cualquier caso, sin necesidad de previsión legal ni de interés propio"]'::jsonb,0,'Art. 19.1 h) Ley 29/1998','La acción popular solo cabe en los casos previstos legalmente.',null),
('14-a66e173709','aux-cm',14,'La Comisión para la Coordinación de la Atención al Ciudadano se reunirá, según el Decreto 21/2002:','["Una vez cada cuatro años", "Todas las semanas", "Al menos dos veces al año", "Solo cuando lo pida un ciudadano"]'::jsonb,2,'Art. 38 Decreto 21/2002 CM','La preside el Director General competente en atención al ciudadano.',null),
('7-4c79f337b5','aux-cm',7,'Los recursos contra disposiciones generales se consideran, a efectos de cuantía:','["De cuantía indeterminada", "De cuantía de 30.000 euros", "De cuantía mínima", "Sin efectos de cuantía"]'::jsonb,0,'Art. 42.2 Ley 29/1998','Se reputan de cuantía indeterminada.',null),
('7-02bfda371e','aux-cm',7,'Cuando se adopten medidas cautelares antes de interponer el recurso, el interesado deberá pedir su ratificación al interponerlo, en el plazo de:','["Un mes desde su notificación", "Dos meses desde su notificación", "Cinco días desde su notificación", "Diez días desde su notificación"]'::jsonb,3,'Art. 136.2 Ley 29/1998','Si no se ratifican, las medidas quedan sin efecto.',null),
('11-e4030fa528','aux-cm',11,'La incapacidad temporal se puede prorrogar, tras los 365 días, por otros:','["30 días", "365 días", "180 días, cuando se presuma que durante ellos el trabajador puede ser dado de alta por curación", "90 días, cuando se presuma que durante ellos el trabajador puede ser dado de alta por curación"]'::jsonb,2,'Art. 169.1 a) TRLGSS','La duración máxima es de 365 días prorrogables por otros 180.',null),
('9-d0d4e5f670','aux-cm',9,'En el procedimiento de licitación con negociación, cuando se limite el número de candidatos, el mínimo será de:','["Cinco", "Dos", "Tres", "Diez"]'::jsonb,2,'Art. 169.2 LCSP','El número mínimo de invitados es tres.',null),
('15-3e94683ed6','aux-cm',15,'Según el art. 20 de la Ley 6/2023, es un órgano colegiado del Sistema de Archivos de la Comunidad de Madrid:','["El Consejo de Estado", "La Agencia Española de Protección de Datos", "La Comisión de Acceso y Valoración de Documentos", "El Tribunal de Cuentas"]'::jsonb,2,'Art. 20 b) Ley 6/2023 CM','También el Consejo de Archivos, la Comisión de Archivo de la Asamblea y la Junta de Expurgo de Documentos Judiciales.',null),
('9-9ebbe301f6','aux-cm',9,'La garantía definitiva puede constituirse, entre otras formas:','["Solo en efectivo, ingresado en la Caja General de Depósitos", "En efectivo o valores, mediante aval o mediante contrato de seguro de caución", "Mediante pagaré personal del contratista o mediante prenda sobre maquinaria, sin necesidad de aval", "Mediante hipoteca sobre bienes inmuebles del contratista o de un tercero, o mediante prenda sobre sus bienes muebles"]'::jsonb,1,'Art. 108.1 LCSP','Son las formas de constitución de la garantía.',null),
('15-972a12bf5e','aux-cm',15,'Las personas al servicio del sector público, al cesar en sus funciones, deberán:','["Entregar los documentos a su cargo a quien les suceda o al archivo público correspondiente", "Entregar los documentos al representante sindical del centro", "Llevárselos a su domicilio", "Conservar una copia de los documentos a su cargo y entregar los originales al órgano que los nombró"]'::jsonb,0,'Art. 73.3 Ley 6/2023 CM','Tienen el deber de custodiarlos y no destruirlos indebidamente.',null),
('10-163f7660e5','aux-cm',10,'La funcionaria víctima de violencia de género que reduzca su jornada en un tercio o menos:','["Pierde las retribuciones básicas", "Solo cobra el 50 %", "Mantendrá sus retribuciones íntegras", "Pierde todas sus retribuciones"]'::jsonb,2,'Art. 49 d) TREBEP','Si la reducción es mayor, la disminución de retribuciones es proporcional.',null),
