('9-ce6eb9b2a5','aux-cm',9,'El valor estimado de los contratos de obras, suministros y servicios se calcula:','["Por el importe total pagadero, incluido el IVA", "Por el importe total pagadero, sin incluir el IVA", "Sin incluir las posibles prórrogas", "Solo con el precio del primer año de ejecución"]'::jsonb,1,'Art. 101.1 a) LCSP','Se tienen en cuenta las eventuales prórrogas y modificaciones previstas.',null),
('11-7035e1499d','aux-cm',11,'La jubilación anticipada por causa no imputable al trabajador permite anticipar la jubilación, como máximo:','["Seis años antes de la edad ordinaria, con 35 años de cotización", "Cuatro años antes de la edad ordinaria, con 33 años de cotización", "Diez años antes", "Dos años antes de la edad ordinaria, con 30 años de cotización"]'::jsonb,1,'Art. 207.1 TRLGSS','Además se exige inscripción como demandante de empleo durante seis meses.',null),
('10-3a7ad98cd4','aux-cm',10,'Los funcionarios pueden solicitar la prolongación de la permanencia en el servicio activo, una vez cumplida la edad de jubilación forzosa, como máximo hasta:','["Sin límite", "Los setenta años", "Los sesenta y siete años", "Los sesenta y ocho años"]'::jsonb,1,'Art. 67.3 TREBEP','La jubilación forzosa se declara al cumplir 65 años.',null),
('10-063b9b7e9c','aux-cm',10,'Quedan excluidas de la obligatoriedad de la negociación:','["Las retribuciones complementarias de los funcionarios", "Las decisiones que afecten a las potestades de organización de las Administraciones Públicas", "Los criterios generales de acceso, carrera, provisión, sistemas de clasificación de puestos y planes de recursos humanos", "La evaluación del desempeño"]'::jsonb,1,'Art. 37.2 a) TREBEP','Las demás opciones son materias objeto de negociación (art. 37.1).',null),
('10-6440fea9a1','aux-cm',10,'Los procedimientos de provisión de puestos de trabajo de los funcionarios de carrera son, con carácter general:','["La entrevista y la valoración del currículum", "La oposición y el concurso-oposición", "El concurso y la libre designación con convocatoria pública", "El concurso y la libre designación sin convocatoria pública"]'::jsonb,2,'Art. 78.2 TREBEP','El concurso es el procedimiento normal de provisión.',null),
('14-5e19252229','aux-cm',14,'Las quejas por retrasos o anomalías en el funcionamiento de los servicios tributarios de la Comunidad de Madrid se enviarán de inmediato a:','["El Defensor del Contribuyente", "La Asamblea de Madrid", "El Tribunal Económico-Administrativo", "La Agencia Tributaria estatal"]'::jsonb,0,'Art. 30.4 Decreto 21/2002 CM','La Oficina de Atención al Ciudadano las remite al Defensor del Contribuyente.',null),
('9-7da06ae743','aux-cm',9,'La publicación de la información de los contratos menores en el perfil de contratante se realizará:','["Anualmente", "Al menos trimestralmente", "Diariamente", "Solo si superan 15.000 euros"]'::jsonb,1,'Art. 63.4 LCSP','Quedan exceptuados los de valor inferior a 5.000 euros pagados mediante anticipo de caja fija o similar.',null),
('9-937ed3f2ed','aux-cm',9,'Los contratos podrán modificarse durante su vigencia, cuando así se haya advertido expresamente en el pliego, hasta un máximo del:','["50 % del precio inicial", "20 % del precio inicial", "100 % del precio inicial", "10 % del precio inicial"]'::jsonb,1,'Art. 204.1 LCSP','Para las modificaciones no previstas en el pliego rige el art. 205.',null),
('13-19756fcc05','aux-cm',13,'Según el art. 6.3 de la LO 3/2007, toda orden de discriminar, directa o indirectamente, por razón de sexo:','["Se considerará en todo caso discriminatoria", "No tiene relevancia jurídica si no llega a ejecutarse", "Solo es discriminatoria si se ejecuta", "Es válida si procede de un superior"]'::jsonb,0,'Art. 6.3 LO 3/2007','La orden de discriminar es en sí misma discriminación.',null),
('10-d452a71d63','aux-cm',10,'La suspensión de funciones determinará la pérdida del puesto de trabajo cuando exceda de:','["Un año", "Tres meses", "Un mes", "Seis meses"]'::jsonb,3,'Art. 90.1 TREBEP','El funcionario suspenso queda privado del ejercicio de sus funciones.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('15-092f2a22ee','aux-cm',15,'El archivo central, según la Ley 6/2023:','["Gestiona los documentos transferidos desde los archivos de gestión hasta su eliminación o transferencia al archivo intermedio", "Custodia los documentos en tramitación", "Custodia los documentos de valor histórico permanente", "Gestiona los documentos transferidos desde el archivo intermedio hasta su eliminación o transferencia al archivo histórico"]'::jsonb,0,'Art. 10 Ley 6/2023 CM','Es la segunda fase del ciclo vital.',null),
('14-0b09330551','aux-cm',14,'La información particular es la relativa a:','["La normativa vigente, las funciones de los órganos y los horarios de las oficinas, dirigida a cualquier ciudadano que la solicite sin necesidad de acreditar interés", "Las funciones de los órganos", "El estado de tramitación de los procedimientos y la identificación de las autoridades y personal responsables, dirigida a los interesados o sus representantes", "Los horarios de las oficinas"]'::jsonb,2,'Art. 9.1 Decreto 21/2002 CM','Solo se facilita a quienes tengan la condición de interesado o a sus representantes.',null),
('14-692023d507','aux-cm',14,'Según el Decreto 21/2002, ¿cuál de estas actividades integra la atención al ciudadano?','["Las sugerencias y reclamaciones", "La potestad sancionadora", "La resolución de recursos de alzada", "La aprobación de presupuestos"]'::jsonb,0,'Art. 1.2 Decreto 21/2002 CM','Integran la atención al ciudadano la información, el registro y las sugerencias y reclamaciones, entre otras.',null),
('9-29c41713db','aux-cm',9,'En la tramitación de emergencia:','["Hay que tramitar siempre un procedimiento abierto con plazos reducidos a la mitad, como en la tramitación urgente", "Se requiere autorización judicial", "No puede contratarse", "El órgano de contratación puede ordenar la ejecución sin obligación de tramitar expediente de contratación"]'::jsonb,3,'Art. 120.1 a) LCSP','El inicio de la ejecución no puede exceder de un mes desde el acuerdo.',null),
('15-b2e2665768','aux-cm',15,'El archivo intermedio, según la Ley 6/2023:','["Custodia los documentos en tramitación o de uso administrativo continuo hasta su transferencia al archivo central, sin conservar documentos de consulta esporádica", "Custodia de forma centralizada los documentos de consulta esporádica hasta su eliminación o transferencia al archivo histórico", "Es el archivo de las oficinas", "Custodia los documentos en tramitación"]'::jsonb,1,'Art. 11 Ley 6/2023 CM','Recibe los documentos del archivo central.',null),
('10-6de4716279','aux-cm',10,'La libre designación con convocatoria pública consiste en:','["Una prueba de conocimientos eliminatoria sobre las funciones del puesto, seguida de la valoración de méritos por una comisión técnica independiente", "La antigüedad del candidato", "Un sorteo entre los candidatos", "La apreciación discrecional por el órgano competente de la idoneidad de los candidatos en relación con los requisitos del puesto"]'::jsonb,3,'Art. 80.1 TREBEP','Se aplica a los puestos que determinen las leyes por su especial responsabilidad.',null),
('14-5aa48edbda','aux-cm',14,'Los Registros de la Comunidad de Madrid NO podrán utilizarse para:','["Presentar recursos administrativos", "Presentar solicitudes", "Presentar sugerencias y quejas sobre el funcionamiento de los servicios públicos de la Comunidad de Madrid", "La remisión masiva de documentos de carácter comercial o publicitario"]'::jsonb,3,'Art. 15.2 Decreto 21/2002 CM','Así lo excluye el Decreto.',null),
('10-3808f6b79a','aux-cm',10,'Según el art. 54.6 TREBEP, los empleados públicos:','["Pueden aceptar regalos de cualquier valor siempre que los declaren a su superior jerárquico en el plazo de diez días desde su recepción y los inscriban en el registro", "Deben declarar los regalos recibidos en su declaración de bienes", "Solo pueden aceptar regalos de otros empleados públicos o de los ciudadanos, siempre que no superen el valor que fije cada Administración en su código ético", "Rechazarán cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía"]'::jsonb,3,'Art. 54.6 TREBEP','Es un principio de conducta.',null),
('7-aa766b830c','aux-cm',7,'Según el art. 105.1, respecto de la ejecución de las sentencias:','["No podrá suspenderse el cumplimiento ni declararse la inejecución total o parcial del fallo", "Podrá suspenderse el cumplimiento cuando lo solicite la Administración condenada por razones de interés público, sin intervención del órgano judicial", "La Administración puede suspenderla libremente", "Podrá declararse la inejecución parcial del fallo si lo autoriza el Gobierno"]'::jsonb,0,'Art. 105.1 Ley 29/1998','Solo cabe imposibilidad material o legal por el cauce del art. 105.2.',null),
('11-87e4531e6e','aux-cm',11,'En la gran incapacidad, el pensionista tiene derecho a una pensión vitalicia incrementada con:','["Un complemento destinado a que pueda remunerar a la persona que le atienda", "Un complemento por mínimos, siempre que carezca de otras rentas", "Una indemnización a tanto alzado por una sola vez, equivalente a veinticuatro mensualidades de la base reguladora", "Una vivienda adaptada a cargo de la entidad gestora y una indemnización a tanto alzado"]'::jsonb,0,'Art. 196.4 TRLGSS','El complemento es el 45 % de la base mínima de cotización más el 30 % de la última base, con un mínimo del 45 % de la pensión.',null),
('9-e8f6768d3b','aux-cm',9,'Cuando haya varios criterios de adjudicación, el plazo máximo para adjudicar será de:','["Quince días desde la apertura de las proposiciones, sin que el pliego pueda fijar otro", "Dos meses desde la apertura de las proposiciones, salvo que el pliego indique otro", "Seis meses desde la apertura de las proposiciones", "Un mes desde la apertura de las proposiciones, salvo que el pliego indique otro"]'::jsonb,1,'Art. 158.2 LCSP','Con un único criterio (el precio), el plazo es de quince días.',null),
('13-18713e4d80','aux-cm',13,'Las acciones positivas para hacer efectivo el derecho a la igualdad pueden adoptarlas:','["Solo el Gobierno y las Administraciones públicas", "Solo los jueces y tribunales en sus sentencias", "Solo las empresas de más de 250 trabajadores, dentro de su plan de igualdad negociado con la representación legal de los trabajadores", "Los poderes públicos y también las personas físicas y jurídicas privadas"]'::jsonb,3,'Art. 11 LO 3/2007','Deben ser razonables y proporcionadas.',null),
('11-509847e188','aux-cm',11,'En la incapacidad temporal por accidente de trabajo o enfermedad profesional, el subsidio se abona:','["Desde el decimosexto día de baja, a cargo de la mutua", "Desde el primer día del mes siguiente", "Desde el cuarto día de baja, a cargo del empresario hasta el decimoquinto", "Desde el día siguiente al de la baja en el trabajo"]'::jsonb,3,'Art. 173.1 TRLGSS','El salario del día de la baja corre a cargo del empresario.',null),
('9-e58e986ba9','aux-cm',9,'Los contratos de suministro de la AGE y sus organismos están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["750.000 euros", "40.000 euros", "5.404.000 euros", "140.000 euros"]'::jsonb,3,'Art. 21.1 LCSP','Para otras entidades el umbral es de 216.000 euros.',null),
('10-ec6e5a7f3e','aux-cm',10,'Durante la suspensión provisional como medida cautelar, el funcionario:','["Percibe íntegramente sus retribuciones hasta que se resuelva el expediente disciplinario", "No percibe ninguna retribución", "Percibirá las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo", "Percibirá las retribuciones complementarias, pero no las básicas"]'::jsonb,2,'Art. 98.3 TREBEP','Si la suspensión se eleva a definitiva, deberá devolver lo percibido.',null),
('9-4720b3e694','aux-cm',9,'Las concesiones de obras y de servicios que comprendan la ejecución de obras tendrán un plazo de duración máximo de:','["40 años", "10 años", "25 años", "5 años"]'::jsonb,0,'Art. 29.6 a) LCSP','Las concesiones de servicios sin obras no sanitarios, 25 años; los sanitarios del art. 29.6 c), 10 años.',null),
('10-ba62d75205','aux-cm',10,'NO pueden formar parte de los órganos de selección:','["Los funcionarios de carrera de otras Administraciones públicas", "Los funcionarios del mismo cuerpo o escala al que se aspira a ingresar y el personal laboral fijo de la misma Administración", "El personal de elección o designación política, los funcionarios interinos y el personal eventual", "El personal laboral fijo y los funcionarios de carrera que hayan preparado a aspirantes en los cinco años anteriores"]'::jsonb,2,'Art. 60.2 TREBEP','Los órganos de selección son colegiados y tienden a la paridad.',null),
('9-0f12306d1b','aux-cm',9,'Para que el contratista pueda ceder sus derechos y obligaciones a un tercero, es requisito que el cedente tenga ejecutado al menos:','["La totalidad de la prestación", "Un 10 % del importe del contrato", "Un 20 % del importe del contrato", "Un 50 % del importe del contrato o de su duración"]'::jsonb,2,'Art. 214.2 b) LCSP','Además, se necesita autorización previa del órgano de contratación.',null),
('13-41b7f2f548','aux-cm',13,'La información a las víctimas de violencia de género sobre sus derechos se garantizará también a las mujeres que, por sus circunstancias personales y sociales, tengan dificultad de acceso, como:','["Solo las mujeres extranjeras en situación irregular", "Solo las empleadas públicas", "Solo las menores de edad, a través de sus representantes legales", "Las mujeres con discapacidad, en formato accesible"]'::jsonb,3,'Art. 18.2 LO 1/2004','También a quienes no dominen las lenguas oficiales (art. 18.3).',null),
('9-ebdd78fcc8','aux-cm',9,'La duración de un acuerdo marco no podrá exceder, salvo casos excepcionales justificados, de:','["Diez años", "Cuatro años", "Dos años", "Cinco años"]'::jsonb,1,'Art. 219.2 LCSP','Es la duración máxima ordinaria de los acuerdos marco.',null),
('7-c3b0d6ad96','aux-cm',7,'En el procedimiento de protección de derechos fundamentales, la demanda se formalizará en el plazo de:','["Quince días", "Ocho días", "Diez días", "Veinte días"]'::jsonb,1,'Art. 118 Ley 29/1998','El plazo de demanda es de ocho días.',null),
('13-9f0885b074','aux-cm',13,'El Observatorio Estatal de Violencia sobre la Mujer es:','["Una organización no gubernamental de ámbito estatal declarada de utilidad pública", "Un órgano colegiado de asesoramiento, evaluación y colaboración institucional", "Una sección especializada de la Fiscalía", "Un juzgado especializado en violencia sobre la mujer con competencia en toda España"]'::jsonb,1,'Art. 30.1 LO 1/2004','Remite al Gobierno y a las CCAA un informe anual.',null),
('11-0718e68b87','aux-cm',11,'Se presume, salvo prueba en contrario, que son constitutivas de accidente de trabajo:','["Todas las enfermedades comunes padecidas durante la vigencia del contrato", "Las lesiones sufridas durante las vacaciones anuales retribuidas", "Las lesiones sufridas en el domicilio un domingo", "Las lesiones que sufra el trabajador durante el tiempo y en el lugar del trabajo"]'::jsonb,3,'Art. 156.3 TRLGSS','Presunción iuris tantum de accidente de trabajo.',null),
('9-1bd4304f7f','aux-cm',9,'La prórroga de un contrato será obligatoria para el empresario siempre que su preaviso se produzca, al menos, con una antelación de:','["Quince días respecto de la finalización del plazo de duración del contrato", "Dos meses respecto de la finalización del plazo de duración del contrato", "Seis meses respecto de la finalización del plazo de duración del contrato", "Un mes"]'::jsonb,1,'Art. 29.2 LCSP','La prórroga no puede producirse por consentimiento tácito de las partes.',null),
('10-fa3f50d7f4','aux-cm',10,'Los nacionales de los Estados miembros de la Unión Europea pueden acceder como funcionarios en igualdad de condiciones que los españoles, salvo a los empleos que impliquen:','["Funciones de atención al público en lengua cooficial", "Participación en el ejercicio del poder público o en las funciones de salvaguardia de los intereses del Estado", "Trabajos en entidades locales", "Funciones administrativas, de gestión o de auxilio, aunque no impliquen ejercicio de potestades públicas"]'::jsonb,1,'Art. 57.1 TREBEP','Los extranjeros con residencia legal pueden acceder como personal laboral (art. 57.4).',null),
('9-3af3e93823','aux-cm',9,'Los contratos de servicios sociales y otros del anexo IV están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["140.000 euros", "750.000 euros", "5.404.000 euros", "216.000 euros"]'::jsonb,1,'Art. 22.1 LCSP','Es un umbral específico para los servicios del anexo IV.',null),
('7-823b12b807','aux-cm',7,'La declaración de incompetencia de un órgano contencioso-administrativo adopta la forma de:','["Sentencia", "Diligencia de ordenación", "Auto", "Providencia"]'::jsonb,2,'Art. 7.3 Ley 29/1998','Se remiten las actuaciones al órgano competente y las partes tienen diez días para comparecer ante él.',null),
('7-e079f8b9c3','aux-cm',7,'La jurisdicción contencioso-administrativa es:','["Prorrogable por decisión del Gobierno", "Voluntaria", "Prorrogable por acuerdo de las partes", "Improrrogable"]'::jsonb,3,'Art. 5.1 Ley 29/1998','Los órganos apreciarán de oficio la falta de jurisdicción.',null),
('7-d63212f374','aux-cm',7,'La Sala de lo Contencioso-administrativo del Tribunal Supremo conoce en única instancia de los recursos contra actos y disposiciones de:','["El Consejo de Ministros", "Los Alcaldes", "Los Delegados del Gobierno", "Los Consejeros de las Comunidades Autónomas"]'::jsonb,0,'Art. 12.1 a) Ley 29/1998','También del CGPJ y del Fiscal General del Estado, entre otros.',null),
('15-41e16c02c4','aux-cm',15,'A falta de Tabla de Valoración, los documentos permanecen en el archivo central hasta su transferencia durante:','["Cinco años desde su ingreso", "Treinta años desde su ingreso", "Quince años desde su ingreso", "Diez años desde su ingreso"]'::jsonb,3,'Art. 51.2 b) Ley 6/2023 CM','Después pasan al archivo intermedio.',null),
('9-5932e7b7d4','aux-cm',9,'Tanto en la concesión de obras como en la de servicios es necesaria la transferencia al concesionario de:','["La propiedad del dominio público", "La titularidad del servicio público", "El riesgo operacional", "La potestad sancionadora"]'::jsonb,2,'Arts. 14.4 y 15.2 LCSP','El concesionario asume el riesgo operacional en la explotación.',null),
('10-a61e25860f','aux-cm',10,'Las pagas extraordinarias de los funcionarios serán:','["Una al año, por el importe de una mensualidad de retribuciones básicas", "Cuatro al año", "Tres al año, cada una por el importe de una mensualidad de retribuciones básicas y de la mitad de las complementarias, que se abonan en marzo, junio y diciembre", "Dos al año, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las complementarias, salvo excepciones"]'::jsonb,3,'Art. 22.4 TREBEP','Son dos pagas al año.',null),
('11-2bd897abad','aux-cm',11,'La prestación por cuidado de menores afectados por cáncer u otra enfermedad grave exige una reducción de jornada de, al menos:','["Un 50 % de su duración", "Un 25 % de su duración", "Un 10 % de su duración", "Un 33 % de su duración"]'::jsonb,0,'Art. 190.1 TRLGSS','Puede mantenerse hasta los 23 años del hijo (26 con discapacidad ≥ 65 % acreditada antes).',null),
('11-709298debc','aux-cm',11,'Si se ingresan las cuotas durante el primer mes natural siguiente al vencimiento del plazo reglamentario, habiendo presentado los documentos de cotización en plazo, el recargo es del:','["10 %", "20 %", "35 %", "5 %"]'::jsonb,0,'Art. 30.1 a) TRLGSS','Si se pagan a partir del segundo mes, el recargo es del 20 %.',null),
('13-66700fbe85','aux-cm',13,'Los proyectos de disposiciones de carácter general y los planes de especial relevancia que se sometan a la aprobación del Consejo de Ministros deberán incorporar:','["Un informe del Consejo de Estado en todo caso", "Un informe sobre su impacto por razón de género", "Un informe económico de la UE", "La firma de todas las Comunidades Autónomas"]'::jsonb,1,'Art. 19 LO 3/2007','Es el informe de impacto de género.',null),
('11-1585e33854','aux-cm',11,'Las bases y tipos de cotización a la Seguridad Social se fijan cada año en:','["Una orden de la Tesorería General de la Seguridad Social", "Los convenios colectivos de cada sector", "La Ley de Presupuestos Generales del Estado", "Un real decreto del Gobierno, previo acuerdo con los agentes sociales"]'::jsonb,2,'Art. 19.1 TRLGSS','La base mínima es, salvo disposición en contrario, el SMI incrementado en un sexto.','abr. 2026 · 1.er ejercicio'),
('9-cbf4bff88c','aux-cm',9,'La inscripción en el Registro Oficial de Licitadores y Empresas Clasificadas del Sector Público acredita, salvo prueba en contrario:','["Las condiciones de aptitud del empresario frente a todos los órganos de contratación del sector público", "Que la empresa ha constituido la garantía definitiva exigida", "Las condiciones de aptitud del empresario solo frente a los órganos de contratación de la Administración General del Estado", "Las condiciones de aptitud del empresario, pero solo frente a los órganos de contratación de la Administración General del Estado"]'::jsonb,0,'Art. 96.1 LCSP','Acredita personalidad, capacidad, representación, solvencia y ausencia de prohibiciones.',null),
('15-46a429be15','aux-cm',15,'La valoración y el régimen de acceso de los documentos judiciales corresponde a:','["La Junta de Expurgo de Documentos Judiciales", "La Comisión de Acceso y Valoración de Documentos", "El Consejo de Archivos", "Cada juzgado individualmente"]'::jsonb,0,'Art. 26.1 Ley 6/2023 CM','La Comisión de Acceso y Valoración excluye los documentos judiciales y los de la Asamblea.',null),
('15-982147dcfc','aux-cm',15,'Las infracciones muy graves de la Ley 6/2023 se sancionan con multa de:','["De 6.001 a 60.000 euros por cada infracción", "De 60.001 a 600.000 euros", "Hasta 6.000 euros", "De 300.001 a 1.000.000 de euros"]'::jsonb,3,'Art. 107.1 Ley 6/2023 CM','Graves: 60.001 a 300.000 €; leves: apercibimiento o multa de hasta 60.000 €.',null),
('13-74fbf88c23','aux-cm',13,'La suspensión y la extinción del contrato de trabajo de la trabajadora víctima de violencia de género:','["Darán lugar a situación legal de desempleo", "Requieren autorización judicial previa", "No dan derecho a prestación por desempleo, salvo que lo reconozca una sentencia", "Se consideran despido disciplinario"]'::jsonb,0,'Art. 21.2 LO 1/2004','El tiempo de suspensión se considera periodo de cotización efectiva.',null),
('11-def02f29f8','aux-cm',11,'Las lesiones permanentes no incapacitantes causadas por accidente de trabajo o enfermedad profesional se indemnizan:','["Con un subsidio mensual mientras dure la lesión", "Con una pensión vitalicia del 55 % de la base reguladora, incompatible con la continuación en la empresa y con cualquier otra prestación de la Seguridad Social", "Por una sola vez, con las cantidades alzadas fijadas en el baremo, sin perjuicio del derecho a continuar en la empresa", "No se indemnizan"]'::jsonb,2,'Art. 201 TRLGSS','Son incompatibles con las prestaciones de incapacidad permanente salvo lesiones independientes.',null),
('11-2aab5248d1','aux-cm',11,'Para tener derecho a la incapacidad temporal derivada de enfermedad común se exige un periodo de cotización de:','["180 días dentro de los cinco años inmediatamente anteriores al hecho causante", "Un año dentro de los diez años inmediatamente anteriores al hecho causante", "365 días en el último año", "No se exige cotización previa"]'::jsonb,0,'Art. 172 a) TRLGSS','En accidente (sea o no de trabajo) y enfermedad profesional no se exige periodo previo.',null),
('15-e7da243c3f','aux-cm',15,'A falta de Tabla de Valoración, los documentos se transfieren del archivo de gestión al central a los:','["Dos años desde la finalización de su tramitación", "Cinco años desde la finalización de su tramitación", "Diez años desde la finalización de su tramitación", "Un año desde el inicio de su tramitación"]'::jsonb,1,'Art. 51.2 a) Ley 6/2023 CM','Plazos subsidiarios: gestión 5 años, central 10 años, intermedio 15 años.',null),
('10-7fddea5e8b','aux-cm',10,'La renuncia voluntaria a la condición de funcionario:','["Habrá de ser manifestada por escrito y será aceptada expresamente por la Administración, salvo que el funcionario esté sujeto a expediente disciplinario o procesado", "Puede manifestarse verbalmente ante el superior jerárquico", "No necesita aceptación expresa y surte efectos desde su presentación, aunque el funcionario esté sujeto a expediente disciplinario o haya sido procesado por un delito", "No está permitida mientras el funcionario no haya cumplido la edad de jubilación, salvo que lo autorice expresamente el Consejo de Gobierno por razones excepcionales de interés público"]'::jsonb,0,'Art. 64 TREBEP','La renuncia no inhabilita para volver a ingresar por el procedimiento de selección.',null),
('9-e8390f7a04','aux-cm',9,'Las entidades del sector público no podrán celebrar otros contratos que:','["Aquellos que sean necesarios para el cumplimiento y realización de sus fines institucionales", "Los que apruebe previamente el Parlamento", "Los que demanden los ciudadanos a través de los procesos de participación ciudadana y presupuestos participativos", "Los que superen 40.000 euros y estén previstos en el plan anual de contratación aprobado por el órgano"]'::jsonb,0,'Art. 28.1 LCSP','Principio de necesidad e idoneidad del contrato.',null),
('15-c59c026ad2','aux-cm',15,'Según la Ley 6/2023, el derecho de acceso a los documentos de titularidad pública:','["Exige siempre motivar la solicitud", "Solo lo tienen los investigadores acreditados", "No exige acreditar interés personal ni motivar la solicitud", "Exige acreditar un interés personal, aunque no es necesario motivar la solicitud"]'::jsonb,2,'Art. 62.2 Ley 6/2023 CM','Todas las personas tienen derecho de acceso (art. 62.1).',null),
('11-76c15a39e8','aux-cm',11,'El derecho al subsidio por incapacidad temporal se extingue, entre otras causas, por el transcurso de:','["365 días naturales desde la baja médica", "545 días naturales desde la baja médica", "730 días naturales desde la primera baja médica", "180 días naturales desde la baja médica"]'::jsonb,1,'Art. 174.1 TRLGSS','Es el plazo máximo total del proceso.',null),
('7-53becc96ce','aux-cm',7,'Los Juzgados de lo Contencioso-administrativo conocen de los recursos contra actos de la Administración autonómica en materia de responsabilidad patrimonial cuya cuantía no exceda de:','["100.000 euros", "60.000 euros", "30.050 euros", "18.000 euros"]'::jsonb,2,'Art. 8.2 c) Ley 29/1998','También de sanciones con multa no superior a 60.000 euros, entre otros supuestos. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('9-60ff1336f4','aux-cm',9,'Según el art. 197 LCSP, la ejecución del contrato se realizará:','["A riesgo y ventura del contratista", "A riesgo del responsable del contrato", "A riesgo de la Administración", "A riesgo compartido al 50 %"]'::jsonb,0,'Art. 197 LCSP','Sin perjuicio de lo previsto para el contrato de obras en el art. 239.',null),
('15-056a0b3b06','aux-cm',15,'El Sistema de Archivos de la Comunidad de Madrid forma parte:','["Del Archivo General de Simancas", "Del Sistema Español de Archivos", "De la Biblioteca Nacional", "Del Consejo de Europa"]'::jsonb,1,'Art. 17.1 Ley 6/2023 CM','Su finalidad es servir a la gestión administrativa, garantizar el acceso y proteger el patrimonio documental.',null),
('14-263dab4f7e','aux-cm',14,'La información especializada, según el Decreto 21/2002, es la que:','["Se refiere al expediente propio del interesado y a la identidad del personal que lo tramita", "Se publica en el BOCM y en el portal de transparencia de la Comunidad", "Se presta por teléfono a través del 012", "Requiere una mayor profundización o consultas complementarias"]'::jsonb,3,'Art. 8.1 Decreto 21/2002 CM','Se distingue de la general y de la particular.',null),
('15-2ccd558aa7','aux-cm',15,'La Comisión de Acceso y Valoración de Documentos emite dictamen preceptivo y vinculante sobre:','["Los recursos de alzada contra las resoluciones de los archivos", "Los presupuestos de la Comunidad", "Las oposiciones de archiveros", "Las Tablas de Valoración y la autorización de eliminación de documentos"]'::jsonb,3,'Art. 24.3 Ley 6/2023 CM','Es un órgano colegiado técnico, multidisciplinar y de participación.',null),
('15-9511c9f661','aux-cm',15,'Según la Ley 6/2023 de la Comunidad de Madrid, el ciclo vital de los documentos es:','["El tiempo de tramitación de un expediente", "El periodo de vigencia administrativa de los documentos, que termina cuando concluye la tramitación del expediente y se transfieren al archivo histórico", "El plazo de prescripción de las acciones derivadas de los documentos, durante el cual deben conservarse en el archivo de gestión sin posibilidad de eliminación", "El conjunto de fases por las que pasan los documentos desde su producción hasta su eliminación o conservación permanente"]'::jsonb,3,'Art. 3.1 d) Ley 6/2023 CM','Definición legal de ciclo vital.',null),
('10-19b5c423c7','aux-cm',10,'Transcurridos tres años desde el nombramiento de un interino en plaza vacante, esta:','["Solo podrá ser ocupada por personal funcionario de carrera, salvo que el proceso selectivo quede desierto", "Se amortiza automáticamente y el interino cesa sin derecho a indemnización, aunque el proceso selectivo no se haya convocado", "Pasa a ser plaza de personal laboral", "Se convierte automáticamente en plaza en propiedad del interino que la ocupa, sin necesidad de proceso selectivo"]'::jsonb,0,'Art. 10.4 TREBEP','Se produce el fin de la relación de interinidad.',null),
('11-24f6116725','aux-cm',11,'La prestación por riesgo durante la lactancia natural se extingue cuando el hijo cumple:','["Dieciocho meses", "Doce meses", "Nueve meses", "Seis meses"]'::jsonb,2,'Art. 189 TRLGSS','Salvo que la beneficiaria se haya reincorporado antes a su puesto.',null),
('11-c5ccc85207','aux-cm',11,'Es un régimen especial de la Seguridad Social según el art. 10.2 TRLGSS:','["El de los trabajadores por cuenta propia o autónomos", "El de los empleados de comercio", "El de los trabajadores de banca y entidades financieras", "El de los trabajadores de la construcción"]'::jsonb,0,'Art. 10.2 a) TRLGSS','También el de trabajadores del mar, funcionarios públicos civiles y militares y estudiantes.',null),
('15-afd0d3fb05','aux-cm',15,'No podrán destruirse documentos de titularidad pública mientras:','["No lo pida el interesado", "Subsista su valor probatorio de derechos y obligaciones de las personas o de los entes públicos", "Estén digitalizados con copia auténtica en un sistema de gestión documental homologado por la Comunidad", "No haya pasado un año"]'::jsonb,1,'Art. 55.1 Ley 6/2023 CM','Tampoco si pueden tener valor informativo o histórico.',null),
('10-7067eb9f23','aux-cm',10,'Es un derecho individual de los empleados públicos del art. 14 TREBEP:','["La formación continua y la actualización permanente de sus conocimientos", "La negociación colectiva y la participación en la determinación de las condiciones de trabajo", "La huelga y el planteamiento de conflictos colectivos de trabajo en su unidad", "El planteamiento de conflictos colectivos de trabajo"]'::jsonb,0,'Art. 14 g) TREBEP','Los demás citados son derechos individuales ejercidos colectivamente (art. 15).',null),
('9-6cd67bad18','aux-cm',9,'Están sujetos a regulación armonizada los contratos de obras y concesiones de valor estimado igual o superior a:','["5.404.000 euros", "1.000.000 euros", "750.000 euros", "216.000 euros"]'::jsonb,0,'Art. 20.1 LCSP','Umbral vigente según el texto consolidado del BOE (los umbrales se revisan periódicamente).',null),
('10-0c21c98fbc','aux-cm',10,'Durante los dos primeros años de excedencia por cuidado de hijos o familiares, el funcionario tiene derecho a:','["Ascender automáticamente de grado", "Nada, salvo el cómputo de antigüedad", "La reserva del puesto de trabajo que desempeñaba", "Seguir percibiendo las retribuciones básicas y la reserva de un puesto en la misma localidad"]'::jsonb,2,'Art. 89.4 TREBEP','Transcurrido ese periodo, la reserva lo es a un puesto en la misma localidad y de igual retribución.',null),
('9-581ee5b2eb','aux-cm',9,'Para que un ente sea medio propio personificado, más del ___ de sus actividades deben llevarse a cabo en el ejercicio de los cometidos que le confíe el poder adjudicador:','["50 %", "80 %", "100 %", "20 %"]'::jsonb,1,'Art. 32.2 b) LCSP','Más del 80 % de su actividad debe dirigirse al poder adjudicador que lo controla.',null),
('14-937e7de848','aux-cm',14,'Según el Decreto 21/2002, la información facilitada al ciudadano:','["No interrumpe ni suspende los plazos establecidos en los procedimientos", "Suspende los plazos del procedimiento durante un mes desde que se solicita", "Interrumpe los plazos de los procedimientos hasta que se notifica la respuesta", "Sustituye a la notificación cuando se presta por escrito"]'::jsonb,0,'Art. 14 Decreto 21/2002 CM','No tiene efectos sobre el procedimiento.',null),
('9-6e97658fed','aux-cm',9,'En la concesión de obras, la contraprestación a favor del concesionario consiste en:','["Un precio fijo pagado por adelantado por la Administración, sin derecho a explotar la obra", "Una subvención anual a cargo de la Administración concedente, sin derecho a explotar la obra", "El derecho a explotar la obra, o dicho derecho acompañado del de percibir un precio", "La propiedad de la obra"]'::jsonb,2,'Art. 14.1 LCSP','La concesión implica la transferencia del riesgo operacional al concesionario.',null),
('9-57c6655e96','aux-cm',9,'Si transcurren dos meses desde la interposición del recurso especial sin que se notifique su resolución:','["Se prorroga otros dos meses", "El contrato se anula", "Se entiende estimado por silencio administrativo y la adjudicación queda sin efecto, debiendo el órgano de contratación adjudicar al siguiente licitador", "El interesado podrá considerarlo desestimado a efectos de interponer recurso contencioso-administrativo"]'::jsonb,3,'Art. 57.5 LCSP','El silencio en el recurso especial es desestimatorio.',null),
('14-e28be7173c','aux-cm',14,'Según el Decreto 21/2002, la atención al ciudadano es:','["La tramitación de recursos administrativos y reclamaciones que presentan los ciudadanos frente a los actos de la Administración de la Comunidad, a través de las oficinas de registro", "El conjunto de actividades y medios que la Administración de la Comunidad pone a disposición de los ciudadanos para el ejercicio de sus derechos y el cumplimiento de sus obligaciones", "Solo el servicio telefónico 012", "El registro de entrada de documentos exclusivamente"]'::jsonb,1,'Art. 1 Decreto 21/2002 CM','El art. 1 define así la atención al ciudadano.',null),
('10-996cb56b06','aux-cm',10,'Las sanciones impuestas por faltas graves prescriben a los:','["Un año", "Dos años", "Tres años", "Seis meses"]'::jsonb,1,'Art. 97 TREBEP','Las muy graves a los tres años y las leves al año.',null),
('9-ae653083f5','aux-cm',9,'Si el licitador propuesto no cumplimenta adecuadamente el requerimiento de documentación en plazo, se le exigirá una penalidad del:','["10 % del precio de adjudicación", "3 % del presupuesto base de licitación, IVA excluido", "1 % del valor estimado", "5 % del presupuesto base de licitación, IVA incluido"]'::jsonb,1,'Art. 150.2 LCSP','Se entiende que ha retirado su oferta.',null),
('9-cb600c5304','aux-cm',9,'Los expedientes de resolución contractual deberán ser instruidos y resueltos en el plazo máximo de:','["Ocho meses", "Tres meses", "Un año", "Seis meses"]'::jsonb,0,'Art. 212.8 LCSP','Plazo máximo de ocho meses.',null),
('13-3d6286f960','aux-cm',13,'Las ausencias o faltas de puntualidad al trabajo de la trabajadora víctima de violencia de género motivadas por su situación física o psicológica:','["Se descuentan del sueldo en todo caso, aunque los servicios sociales de atención o de salud acrediten que están motivadas por su situación física o psicológica", "Se considerarán justificadas y serán remuneradas cuando así lo determinen los servicios sociales de atención o de salud", "Requieren autorización judicial", "Serán siempre sancionadas como falta leve, aunque los servicios sociales de atención o de salud acrediten que derivan de su situación"]'::jsonb,1,'Art. 21.4 LO 1/2004','Deben comunicarse a la empresa a la mayor brevedad.',null),
('15-a8283292f8','aux-cm',15,'Según la Ley 6/2023, la eliminación de documentos de titularidad pública:','["Está prohibida en todo caso", "Solo la autoriza un juez", "Solo puede hacerse conforme a las Tablas de Valoración dictaminadas favorablemente por la Comisión competente", "Puede hacerla libremente cada órgano productor una vez transcurridos los plazos de conservación fijados en su normativa interna"]'::jsonb,2,'Art. 55.2 Ley 6/2023 CM','Debe expedirse certificación de la destrucción.',null),
('7-6b4c752060','aux-cm',7,'En caso de inactividad, si la Administración no da cumplimiento a lo reclamado o no llega a un acuerdo con los interesados, estos pueden recurrir si transcurre desde la reclamación un plazo de:','["Seis meses", "Tres meses", "Un mes", "Diez días"]'::jsonb,1,'Art. 29.1 Ley 29/1998','Pasados tres meses desde la reclamación, cabe recurso contra la inactividad.',null),
('10-213c4c50cb','aux-cm',10,'Las faltas muy graves prescriben a los:','["Dos años", "Seis meses", "Cinco años", "Tres años"]'::jsonb,3,'Art. 97 TREBEP','Las graves a los dos años y las leves a los seis meses.',null),
('15-2340a10102','aux-cm',15,'Las funciones archivísticas según el art. 41.1 de la Ley 6/2023 incluyen:','["La imposición de sanciones", "La aprobación de las normas sobre archivos, la imposición de sanciones y la eliminación libre de documentos", "Solo la custodia y conservación de los documentos, sin incluir su descripción, valoración ni el servicio a los ciudadanos", "Identificación, valoración, organización, descripción, conservación, custodia, acceso y servicio"]'::jsonb,3,'Art. 41.1 Ley 6/2023 CM','Son funciones de carácter transversal.',null),
('7-570a127e50','aux-cm',7,'El recurso de apelación contra sentencias es admisible, salvo que la ley disponga otra cosa:','["Sin efectos", "En ambos efectos", "Solo en un efecto", "Solo en efecto devolutivo"]'::jsonb,1,'Art. 83.1 Ley 29/1998','La apelación no impide la ejecución provisional de la sentencia (art. 84).',null),
('10-b7df4df257','aux-cm',10,'A efectos de vacaciones de los funcionarios, los sábados:','["No se consideran días hábiles, salvo en los horarios especiales", "Computan doble", "Se consideran hábiles solo en agosto", "Se consideran siempre días hábiles, cualquiera que sea el horario del funcionario"]'::jsonb,0,'Art. 50.1 TREBEP','Las vacaciones son de 22 días hábiles.',null),
('7-ad294cded7','aux-cm',7,'La Administración debe remitir el expediente administrativo al juzgado o tribunal en el plazo improrrogable de:','["Un mes natural", "Diez días hábiles desde la reclamación", "Veinte días", "Dos meses"]'::jsonb,2,'Art. 48.3 Ley 29/1998','El expediente se remite en veinte días.',null),
('15-f555ef6c94','aux-cm',15,'El plazo máximo para resolver los procedimientos sancionadores de la Ley 6/2023 es de:','["Un año", "Dos meses", "Seis meses", "Tres meses"]'::jsonb,2,'Art. 114 Ley 6/2023 CM','Plazo de resolución de seis meses.',null),
('9-83f87336a2','aux-cm',9,'Los órganos de contratación designarán un responsable del contrato al que corresponderá:','["Fijar el precio del contrato y resolver las reclamaciones de los licitadores sobre la adjudicación, previo informe de la mesa de contratación y de los servicios jurídicos", "Resolver el recurso especial", "Supervisar su ejecución y adoptar las decisiones y dictar las instrucciones necesarias para asegurar la correcta realización de la prestación", "Adjudicar el contrato, fijar el precio de licitación y resolver el recurso especial en materia de contratación que interpongan los licitadores excluidos"]'::jsonb,2,'Art. 62.1 LCSP','Su designación es obligatoria.',null),
('10-7a269cc3d5','aux-cm',10,'La parte de jornada no realizada sin justificación dará lugar a:','["La deducción proporcional de haberes, que no tendrá carácter sancionador", "Ninguna consecuencia económica, aunque deberá recuperarse en otro momento de la semana", "La separación del servicio", "Una sanción disciplinaria grave, previa tramitación del expediente correspondiente"]'::jsonb,0,'Art. 30.1 TREBEP','La deducción no es una sanción.',null),
('7-477288c6b8','aux-cm',7,'En el procedimiento abreviado, el juez dictará sentencia en el plazo de:','["Veinte días", "Un mes desde la presentación de la demanda", "Diez días desde la celebración de la vista", "Cinco días desde la presentación de la demanda"]'::jsonb,2,'Art. 78.20 Ley 29/1998','Se dicta en diez días desde la vista.',null),
('10-b46b819b8a','aux-cm',10,'Para participar en la promoción interna, los funcionarios deben poseer una antigüedad de, al menos:','["Un año de servicio activo en el mismo cuerpo o escala", "Dos años de servicio activo en el inferior subgrupo o grupo de clasificación profesional", "Tres años de servicio activo en el mismo cuerpo o escala, de los cuales al menos uno en la misma Administración", "Cinco años de servicio activo en cualquier cuerpo o escala de la misma Administración pública"]'::jsonb,1,'Art. 18.2 TREBEP','Además de la titulación y demás requisitos exigidos.',null),
('11-d0f4d56b21','aux-cm',11,'Las pensiones contributivas se revalorizan al comienzo de cada año en función de:','["El valor medio de las tasas de variación interanual del IPC de los doce meses previos a diciembre del año anterior", "El IPREM", "El SMI", "El crecimiento del PIB y la evolución de la masa salarial de los afiliados en los doce meses previos"]'::jsonb,0,'Art. 58.2 TRLGSS','Si el valor es negativo, el importe de las pensiones no varía.',null),
('13-6ac395a8a6','aux-cm',13,'Según la LO 3/2007, se considera discriminación por razón de sexo cualquier trato adverso o efecto negativo producido como consecuencia de:','["Su afiliación a un partido político o a un sindicato", "Su cambio de domicilio", "La presentación por una persona de una queja, reclamación, denuncia o demanda destinada a impedir su discriminación", "Su ascenso profesional o la obtención de un puesto de libre designación tras un procedimiento de provisión con convocatoria pública"]'::jsonb,2,'Art. 9 LO 3/2007','Es la garantía de indemnidad frente a represalias.',null),
('7-c11998167b','aux-cm',7,'En caso de vía de hecho, el interesado puede formular requerimiento a la Administración y, si no es atendido en el plazo de:','["Tres meses, podrá interponer recurso de alzada ante el superior jerárquico", "Un mes, podrá interponer recurso de alzada ante el superior jerárquico del órgano", "Diez días, podrá deducir directamente recurso contencioso-administrativo", "Veinte días"]'::jsonb,2,'Art. 30 Ley 29/1998','Si el requerimiento no se formula o no se atiende en diez días, cabe recurso directo.',null),
('9-1b1064451d','aux-cm',9,'Las penalidades por demora en la ejecución, salvo que el pliego disponga otras, serán diarias en la proporción de:','["0,10 euros por cada 1.000 euros", "1 euro por cada 100 euros", "5 euros por cada 1.000 euros del precio del contrato, IVA incluido", "0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido"]'::jsonb,3,'Art. 193.3 LCSP','Cada vez que las penalidades alcancen un múltiplo del 5 % del precio se puede resolver el contrato.',null),
('7-05d3e4376f','aux-cm',7,'Las decisiones que adopte el juez sobre cuestiones prejudiciales o incidentales no pertenecientes al orden contencioso-administrativo:','["Deben confirmarse por el Tribunal Supremo", "Vinculan a los tribunales penales", "Producen efectos de cosa juzgada en todos los órdenes", "No producirán efectos fuera del proceso en que se dicten"]'::jsonb,3,'Art. 4.2 Ley 29/1998','Solo producen efectos en el proceso en que se dictan.',null),
('11-e13d6bc5f7','aux-cm',11,'La administración y gestión de servicios sanitarios corresponde, como entidad gestora, a:','["Las mutuas colaboradoras con la Seguridad Social", "La TGSS", "El Instituto Nacional de Gestión Sanitaria (INGESA)", "El IMSERSO"]'::jsonb,2,'Art. 66.1 b) TRLGSS','El INGESA es la entidad gestora sanitaria.',null),
('10-b98c33766a','aux-cm',10,'Durante los dos primeros meses de excedencia por razón de violencia de género, la funcionaria tendrá derecho a:','["No percibir retribución alguna, aunque se le reserva el puesto de trabajo y se computa el tiempo a efectos de antigüedad", "Percibir las retribuciones íntegras y, en su caso, las prestaciones familiares por hijo a cargo", "Percibir el 50 % de sus retribuciones básicas y complementarias", "Percibir solo las retribuciones básicas, pero no las complementarias ni las prestaciones familiares por hijo a cargo"]'::jsonb,1,'Art. 89.5 TREBEP','Durante los seis primeros meses tiene reserva del puesto, prorrogable por periodos de tres meses hasta dieciocho.',null),
('11-193e3cb7f4','aux-cm',11,'La pensión vitalicia por incapacidad permanente total puede sustituirse excepcionalmente por una indemnización a tanto alzado cuando el beneficiario sea menor de:','["Cuarenta y cinco años", "Cincuenta años", "Sesenta y cinco años", "Sesenta años"]'::jsonb,3,'Art. 196.2 TRLGSS','Es una sustitución excepcional.',null),
('7-d5d814fe13','aux-cm',7,'Los Juzgados Centrales de lo Contencioso-administrativo conocen, entre otros, de los recursos contra actos de los organismos públicos con competencia en:','["Una Comunidad Autónoma", "Un solo municipio", "Una sola provincia o un solo partido judicial", "Todo el territorio nacional"]'::jsonb,3,'Art. 9.1 c) Ley 29/1998','Conocen en primera o única instancia de los recursos contra disposiciones y actos de esos organismos en los términos del art. 9. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('15-a081cc7e63','aux-cm',15,'Las Tablas de Valoración se aprueban mediante:','["Decreto del Presidente de la Comunidad", "Orden de la Consejería competente en materia de archivos", "Ley de la Asamblea de Madrid, a propuesta del Gobierno", "Resolución de cada archivo"]'::jsonb,1,'Art. 56.1 a) Ley 6/2023 CM','Previo dictamen de la Comisión competente.',null),
('7-cee9f290be','aux-cm',7,'Las medidas cautelares podrán acordarse cuando la ejecución del acto o la aplicación de la disposición:','["Pudieran hacer perder su finalidad legítima al recurso, previa valoración de todos los intereses en conflicto", "Lo pida el Ministerio Fiscal o la Administración demandada, sin necesidad de valorar los intereses en conflicto ni la finalidad del recurso", "Haya sido recurrida en alzada o en reposición y no se haya resuelto el recurso", "Cause cualquier molestia o perjuicio al recurrente, aunque no haga perder su finalidad al recurso ni se valoren los intereses en conflicto"]'::jsonb,0,'Art. 130.1 Ley 29/1998','Pueden denegarse si causan perturbación grave de los intereses generales o de tercero.',null),
('9-377a5910fc','aux-cm',9,'Si se interpone recurso especial contra la adjudicación, como regla general:','["El recurso no produce efectos suspensivos", "Quedará en suspenso la tramitación del procedimiento", "La adjudicación se anula automáticamente y se retrotrae el procedimiento", "El contrato se formaliza igualmente"]'::jsonb,1,'Art. 53 LCSP','Salvo en contratos basados en acuerdos marco o sistemas dinámicos de adquisición.',null),
('11-5737994ce3','aux-cm',11,'Para tener derecho a la prestación por nacimiento y cuidado de menor, a las personas trabajadoras menores de 21 años:','["No se les exige periodo mínimo de cotización", "Se les exigen 90 días cotizados dentro de los siete años inmediatamente anteriores al inicio del descanso", "Se les exige un año cotizado a lo largo de su vida laboral", "Se les exigen 180 días cotizados"]'::jsonb,0,'Art. 178.1 a) TRLGSS','Entre 21 y 26 años no cumplidos se exigen 90 días en los siete años anteriores (o 180 en la vida laboral).',null),
('10-c4e059e7ac','aux-cm',10,'La designación del personal directivo profesional atenderá a principios de:','["Libre designación política por el titular del órgano superior", "Sorteo entre funcionarios del subgrupo A1", "Antigüedad en el cuerpo, y en caso de empate, mérito y capacidad mediante procedimientos que garanticen la publicidad y la concurrencia", "Mérito y capacidad y criterios de idoneidad, mediante procedimientos que garanticen la publicidad y concurrencia"]'::jsonb,3,'Art. 13.2 TREBEP','Así lo establece el art. 13.2.',null),
('10-6fd63d0e81','aux-cm',10,'Los trienios consisten en una cantidad, igual para cada subgrupo o grupo, por cada:','["Año de servicio", "Cinco años de servicio", "Dos años de servicio", "Tres años de servicio"]'::jsonb,3,'Art. 23 b) TREBEP','Retribución básica por antigüedad.',null),
('9-810fad9409','aux-cm',9,'El procedimiento abierto simplificado puede utilizarse en contratos de obras de valor estimado igual o inferior a:','["2.000.000 de euros", "5.538.000 euros", "500.000 euros, IVA excluido", "100.000 euros, IVA excluido"]'::jsonb,0,'Art. 159.1 LCSP','Para suministros y servicios hay un umbral inferior.',null),
('7-16315e0d97','aux-cm',7,'La sentencia estimará el recurso contencioso-administrativo cuando la disposición o el acto incurran en:','["Defectos de forma que produzcan indefensión, pero no la desviación de poder", "Cualquier infracción del ordenamiento jurídico, incluso la desviación de poder", "Vulneración de derechos fundamentales y libertades públicas susceptibles de amparo constitucional", "Causas de nulidad de pleno derecho, pero no en meros vicios de anulabilidad del acto"]'::jsonb,1,'Art. 70.2 Ley 29/1998','Si se ajusta a Derecho, el recurso se desestima.',null),
('9-17a74a29ca','aux-cm',9,'Contra la resolución del recurso especial en materia de contratación:','["Solo procederá la interposición de recurso contencioso-administrativo", "Cabe recurso de alzada ante el titular del departamento", "Cabe recurso potestativo de reposición ante el mismo tribunal administrativo, y después recurso contencioso-administrativo", "No cabe ningún recurso"]'::jsonb,0,'Art. 59.1 LCSP','La resolución es directamente ejecutiva.',null),
('10-64c04b4741','aux-cm',10,'Las retribuciones de los funcionarios de carrera se clasifican en:','["Ordinarias y extraordinarias", "Directas e indirectas", "Básicas y complementarias", "Fijas y variables"]'::jsonb,2,'Art. 22.1 TREBEP','Las pagas extraordinarias son dos al año.',null),
('14-25579bb914','aux-cm',14,'Según el Decreto 21/2002, la respuesta a la sugerencia o reclamación debe procurar producirse dentro de:','["Los tres meses siguientes a su recepción", "Los diez días naturales siguientes a su recepción", "Un mes desde su recepción, ampliable por otro mes si la complejidad lo exige", "Los quince días hábiles siguientes a su recepción"]'::jsonb,3,'Art. 31.4 Decreto 21/2002 CM','Se procura contestar en quince días hábiles.',null),
('10-d341a184a7','aux-cm',10,'Los Pactos y Acuerdos, salvo que se establezca otra cosa:','["Se prorrogarán de año en año si no media denuncia expresa de una de las partes", "Caducan al año de su firma, salvo que se renueven expresamente", "Se prorrogarán por periodos de cuatro años, salvo que una de las partes los denuncie con seis meses de antelación", "Duran cuatro años improrrogables"]'::jsonb,0,'Art. 38.11 TREBEP','Prórroga anual salvo denuncia.',null),
('14-dacf38de24','aux-cm',14,'En el esquema del Decreto 21/2002, en cada Consejería existe:','["Un Punto de Información y Atención al Ciudadano, dependiente de su Secretaría General Técnica", "Una Oficina de Atención al Ciudadano, dependiente directamente del Consejero", "Una Oficina del Defensor del Pueblo", "Un Punto de Información y Atención al Ciudadano, dependiente de la Dirección General de Calidad de los Servicios y Atención al Ciudadano"]'::jsonb,0,'Art. 35 Decreto 21/2002 CM','Los Coordinadores de Atención al Ciudadano se designan en las Secretarías Generales Técnicas.',null),
('10-8d68710888','aux-cm',10,'Por fallecimiento de un familiar de primer grado en la misma localidad, el permiso es de:','["Cinco días hábiles", "Tres días hábiles", "Dos días hábiles", "Un día"]'::jsonb,1,'Art. 48 a) TREBEP','Si es en distinta localidad, cinco días hábiles.',null),
('14-fd274e8456','aux-cm',14,'La información que se facilita al ciudadano tiene carácter:','["De notificación oficial a efectos del cómputo de plazos", "Vinculante para la Administración que la facilita", "Meramente ilustrativo, sin que pueda entenderse como interpretación normativa ni generar derechos", "Meramente ilustrativo, aunque vincula a la Administración cuando se facilita por escrito y genera derechos para quien la recibe"]'::jsonb,2,'Art. 14 Decreto 21/2002 CM','No interrumpe ni suspende plazos ni sirve de notificación.',null),
('13-dc0e4c7cd9','aux-cm',13,'Los servicios de asistencia social integral a las víctimas de violencia de género responderán, entre otros, a los principios de:','["Gratuidad parcial, voluntariedad, subsidiariedad respecto de los servicios generales y atención exclusiva en horario de oficina", "Secreto, discrecionalidad, gratuidad parcial, subsidiariedad respecto de los servicios generales y atención en horario de oficina", "Centralización y uniformidad", "Atención permanente, actuación urgente, especialización de prestaciones y multidisciplinariedad profesional"]'::jsonb,3,'Art. 19.1 LO 1/2004','Son los principios de la asistencia social integral.',null),
('11-ecc6fe5cd8','aux-cm',11,'El derecho a la devolución de ingresos indebidos en materia de Seguridad Social prescribe a los:','["Cinco años desde el día siguiente al ingreso", "Diez años desde el día siguiente al ingreso", "Un año desde el día siguiente al ingreso", "Cuatro años desde el día siguiente al ingreso"]'::jsonb,3,'Art. 26.3 TRLGSS','Coincide con el plazo de prescripción de las deudas por cuotas.',null),
('9-1b8c22b6c9','aux-cm',9,'En los contratos de servicios del anexo IV y en los que tengan por objeto prestaciones de carácter intelectual, los criterios relacionados con la calidad deben representar, al menos:','["El 51 % de la puntuación asignable", "El 30 % de la puntuación asignable", "El 75 % de la puntuación asignable", "El 40 % de la puntuación asignable"]'::jsonb,0,'Art. 145.4 LCSP','Garantiza que la calidad pese más que el precio en esos contratos.',null),
('9-bec4985db4','aux-cm',9,'NO procede el recurso especial en materia de contratación respecto de los procedimientos de adjudicación que se sigan:','["Mediante procedimiento restringido", "Mediante procedimiento abierto", "Por el trámite de emergencia", "En contratos de servicios"]'::jsonb,2,'Art. 44.4 LCSP','No cabe recurso especial en la tramitación de emergencia.',null),
('7-22be046e51','aux-cm',7,'En los recursos con estimación parcial de las pretensiones, como regla general:','["Las paga siempre el recurrente que haya visto rechazada cualquiera de sus pretensiones", "Cada parte abonará las costas causadas a su instancia y las comunes por mitad", "Las paga la parte cuyas pretensiones hayan sido desestimadas en mayor medida, salvo que el órgano aprecie temeridad", "Las paga siempre la Administración demandada"]'::jsonb,1,'Art. 139.1 Ley 29/1998','Salvo que el órgano aprecie mala fe o temeridad en alguna de las partes.',null),
('10-e558abc73f','aux-cm',10,'Las Mesas de Negociación quedarán válidamente constituidas cuando las organizaciones sindicales presentes representen, como mínimo:','["El 10 % de los miembros de los órganos unitarios de representación", "La totalidad de los miembros de los órganos unitarios de representación", "La mayoría absoluta de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "Un tercio de los miembros de los órganos unitarios de representación en el ámbito de que se trate"]'::jsonb,2,'Art. 35.1 TREBEP','Ninguna de las partes puede superar quince miembros (art. 35.4).',null),
('11-93233294f4','aux-cm',11,'La prestación temporal de viudedad tiene una duración de:','["Seis meses", "Cinco años", "Un año", "Dos años"]'::jsonb,3,'Art. 222 TRLGSS','Se concede cuando no se reúnen los requisitos de la pensión de viudedad por el periodo de matrimonio.',null),
('10-4f9a330a04','aux-cm',10,'Los órganos de selección no podrán proponer el acceso a la condición de funcionario de un número superior de aprobados al de plazas convocadas:','["Salvo en la Administración Local, cuando lo acuerde el Pleno", "Salvo que la convocatoria prevea otra cosa", "En ningún caso, y cualquier propuesta que lo contravenga será nula de pleno derecho", "Salvo que lo solicite el tribunal"]'::jsonb,1,'Art. 61.8 TREBEP','Regla general con la excepción prevista.',null),
('13-592fb43728','aux-cm',13,'La Delegación del Gobierno contra la Violencia de Género, entre otras funciones:','["Dicta resoluciones vinculantes para los juzgados de violencia sobre la mujer", "Dirige y coordina a la policía judicial en las investigaciones de violencia de género y dicta instrucciones a los juzgados especializados", "Elabora la Macroencuesta de Violencia contra las Mujeres y está legitimada ante los órganos jurisdiccionales", "Impone sanciones administrativas a los agresores y dirige las investigaciones de la policía judicial en los casos más graves"]'::jsonb,2,'Art. 29 LO 1/2004','Formula las políticas públicas en materia de violencia de género.',null),
('9-97ea903062','aux-cm',9,'Si la demora en el pago por la Administración fuese superior a seis meses, el contratista tendrá derecho a:','["Ceder el contrato a un tercero sin necesidad de autorización del órgano de contratación", "Resolver el contrato y al resarcimiento de los perjuicios", "Una prórroga del contrato por un plazo igual al de la demora", "Suspender la ejecución, pero no resolver el contrato"]'::jsonb,1,'Art. 198.6 LCSP','Si la demora supera cuatro meses puede suspender el cumplimiento del contrato.',null),
